import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.0AV_2kjq.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://moviplayer.com/docs/changelog"}]]},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),r={name:"changelog.md"};function i(s,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="_0-4-1-2026-10-01" tabindex="-1">[0.4.1] - 2026-10-01 <a class="header-anchor" href="#_0-4-1-2026-10-01" aria-label="Permalink to &quot;[0.4.1] - 2026-10-01&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><p><strong>Playlist / queue</strong>: <code>playlist</code> + <code>autoadvance</code> — Next/Previous, <code>Shift+N</code>/<code>Shift+P</code>, and lock-screen/headset skip, all wired up for free. A <code>src</code>-less item hands loading back to the host while the element keeps the transport controls.</p></li><li><p><strong>Take over the <code>&lt;video&gt;</code> elements a page already has</strong>: <code>upgradeVideoElements()</code> (or a zero-JS <code>data-upgrade</code> script tag) drops a <code>&lt;movi-player&gt;</code> in place of an existing <code>&lt;video&gt;</code> or video.js instance, carrying over its attributes and children and keeping the old element as a live proxy so existing page scripts keep working.</p></li><li><p><strong><code>thumb=&quot;precise&quot;</code></strong>: walks from the keyframe to the exact hovered frame instead of showing the keyframe before it — the fix that matters on long-GOP downloads. On by default in the extensions and the web app now.</p></li><li><p><strong>Thumbnail tracks read the video.js/JW Player way</strong> (<code>&lt;track kind=&quot;metadata&quot; label=&quot;thumbnails&quot;&gt;</code>), replacing the old bespoke <code>storyboard</code> attribute; a <code>storyboard</code> property still covers a board worked out at runtime.</p></li><li><p><strong>A top-right corner control placement</strong> (<code>placement: &quot;top&quot;</code>) for session-level controls (cast, share, close), a <strong>centred bar control</strong> (<code>placement: &quot;center&quot;</code>), and <strong>fullscreen-only controls</strong> (<code>screen:</code>).</p></li><li><p><strong>External subtitle files from a picker</strong>: <code>addSubtitleTrack()</code> / <code>addSubtitleFile()</code> and a <code>subtitlepicker</code> menu row load an SRT/VTT/TTML file sitting next to the video, no reload required.</p></li><li><p><strong>DRM-protected content says so</strong>: shows &quot;Protected Video&quot; with a plain explanation instead of a generic error, and plays through a packager&#39;s clear lead instead of stalling and retrying forever.</p></li><li><p><strong>Google Drive picker</strong> no longer scrolls the page away when it opens, and resumes playback automatically when closed.</p></li><li><p><strong>ChromeOS Files app integration and lock-screen skip</strong> for the Chrome extension.</p></li><li><p><strong>Firefox extension and Chrome&#39;s toolbar icon</strong> open the full player page directly instead of a popup, and both work from an incognito/private window.</p></li><li><p><strong>In-player debug console</strong> gets a level filter and search.</p></li><li><p><strong>A centred bar control</strong> (<code>placement: &quot;center&quot;</code>) and <strong>fullscreen-only controls</strong> (<code>screen: &quot;fullscreen&quot; | &quot;windowed&quot;</code>).</p></li><li><p><strong><code>spinnerdelay</code> takes two numbers</strong> — a mid-play stall&#39;s wait, then the opening&#39;s (<code>spinnerdelay=&quot;0.25 1&quot;</code>).</p></li><li><p><strong><code>smoothwarning</code></strong>: one attribute shows &quot;This video (or audio) may not play smoothly&quot; in plain language — including &quot;it plays fine at normal speed&quot; when the speed is the cause — on load and on every speed change; a cancelable <code>smoothwarning</code> event lets a page show its own.</p></li><li><p><strong>Ask whether something will play smoothly</strong>: <code>MoviElement.canPlaySmoothly(url | file | query, { rate })</code>, <code>element.canPlaySmoothly()</code>, and <code>MoviPlayer.assessPlayback()</code> — <code>playable</code>, <code>smooth</code>, <code>powerEfficient</code>, which decoder would carry it, and plain-language <code>reasons</code>. The same judgement the player uses to pick a rendition, plus a hardware ceiling at 8K60.</p></li><li><p><strong>A build a plain <code>&lt;script&gt;</code> tag can load</strong>: <code>dist/element.global.js</code> and <code>dist/element.slim.global.js</code> (subpaths <code>movi-player/element/global</code>, <code>/element/slim/global</code>); <code>jsdelivr</code>/<code>unpkg</code> point at it, so a CDN&#39;s default install snippet works as printed.</p></li><li><p><strong>Seamless loop</strong>: a video-only file turns over without a black frame or freeze. <code>loop</code> gained a grammar — bare/<code>one</code> repeats the item, <code>loop=&quot;all&quot;</code> the queue, a number is the gap between items — plus a <code>loop</code> event and <code>loopCount</code>.</p></li><li><p><strong><code>shuffle</code></strong>: the queue in a random order, a fresh order each pass, <code>reshuffle()</code>, <code>shufflechange</code>.</p></li><li><p><strong>Shuffle and repeat in the playlist panels</strong> of the Chrome/Firefox extensions and the web app, driven by the element so the panel and the context menu can&#39;t disagree.</p></li><li><p><strong>Auto English captions, made in the browser.</strong> Two APIs make it possible and the web app puts them together. <code>decodeAudio()</code> hands back the soundtrack as 16 kHz mono samples — the shape speech models take — from any point in the file, without playing it and on its own WASM instance, so a player already playing is not disturbed. <code>appendSubtitleCues()</code> writes a subtitle track as lines arrive, in any order, and shows a cue straight away if it covers the current moment; with <code>pending: true</code> the track is listed before its first line, with a turning ring where its language badge goes, and <code>removeSubtitleCues()</code> takes it away again. In the web app, &quot;Auto captions&quot; in the right-click menu puts &quot;English (auto)&quot; in the subtitle list at once, turning until its first line is ready (and gone again, with a note, if the video has no speech), and runs Whisper (base, through transformers.js) in a worker on 30-second windows and adds what it hears as &quot;English (auto)&quot; — translating when the speech isn&#39;t English. It starts at the playhead, follows a seek, rests once 90 seconds ahead, and fills in whatever was skipped; lines are cut to readable length and laid over the stretches that actually have voice in them, and the loops a small model falls into on music (&quot;I&#39;m not a man, I&#39;m not a man…&quot;) are dropped. Silero VAD (2 MB) decides which stretches have someone speaking: a window with no speech never reaches Whisper — a song&#39;s 30-second instrumental intro was passed over in 0.2s — words it would invent over music are thrown out, and cues are timed to the voice rather than to whatever is loud. What has been made is kept per video in IndexedDB (a local file by name, size and date; a link by its address), so opening the video again shows its captions straight away without loading the model, and only the parts never reached are made. Nothing leaves the browser except the models, about 80 MB, downloaded once. Measured on a laptop: 30 seconds of speech in 3-10 seconds, with no frames dropped from playback alongside it.</p></li><li><p><strong>Dividers on the control bar are public.</strong> The line between the track controls and the viewing controls can be switched off (<code>controlslist=&quot;nodivider&quot;</code>), restyled (<code>--movi-divider-color</code>, <code>--movi-divider-width</code>, <code>--movi-divider-height</code>, <code>--movi-divider-gap</code>, <code>::part(controls-divider)</code>), and used as an anchor (<code>after: &quot;divider&quot;</code>). A page can add its own with <code>addControl({ id, divider: true })</code>, placed like any control — including inside a capsule with <code>group</code> — and as a rule in the context menu with <code>placement: &quot;menu&quot;</code>. A divider left with nothing visible on one side of it in its capsule hides itself, so a control unavailable for this source doesn&#39;t strand a line at the end of a pill.</p></li><li><p><strong><code>posterdelay</code></strong>: how long to hold the OPENING poster back, in milliseconds. Default <code>0</code> — paint it at once, which is what a player without the attribute has always done. It is for a host that prefetches: when the first frame is already on its way, a poster that appears and is replaced a moment later is a flash the viewer reads as a fault rather than a cover, so a load that finishes inside the wait now shows no poster at all and the picture is simply there. Only the opening poster waits; one replacing a picture already on screen is unaffected.</p></li><li><p><strong>Captions go where the viewer puts them</strong>: drag a subtitle anywhere in the picture and it stays — across seeks, sources and sessions — with a double-click to reset and a hint that says so until the reset is used once. <code>controlslist=&quot;nosubtitledrag&quot;</code> turns it off.</p></li><li><p><strong>The browser extensions can hand a page&#39;s own video to MoviPlayer</strong>: an opt-in toggle replaces a site&#39;s <code>&lt;video&gt;</code> in place, for a file at a URL only (MSE/DRM streaming sites are left alone), hides the site&#39;s own player chrome, and — with site access — adds the CORS header the file&#39;s host never sent so the player can read it.</p></li><li><p><strong>The audio strip says where the pointer is pointing</strong>: its scrubber shows the time under the pointer on hover and drag.</p></li><li><p><strong>The home page hands over the install line</strong>: <code>npm install movi-player</code>, one click to copy.</p></li><li><p><strong><code>resumekey</code></strong>: files the resume position under a name the host chooses instead of under the title. The title is the player&#39;s guess — two episodes can share one, a corrected title is still the same video, and a source the player cannot name got no resume at all. An id is the host&#39;s fact, and being an attribute it is known before the file opens, so the position is offered without waiting for metadata.</p></li><li><p><strong>The takeover brings the site&#39;s quality ladder with it.</strong> A <code>&lt;video&gt;</code> holds one file — whichever rung the site&#39;s player picked — so a page that plainly offered 360/720/1080 used to become a player with one quality and no menu. The qualities are now read from JW&#39;s playlist item, from video.js&#39;s own player, or from the <code>&lt;video&gt;</code>&#39;s <code>&lt;source&gt;</code> children, whichever has them. A manifest among them is left out (it has its own ladder inside it), and sources that say nothing about themselves are left alone: an mp4 with a webm beside it is a format fallback, not a choice anyone offered.</p></li><li><p><strong>A toolbar popup for the browser extensions</strong>, the way an ad blocker&#39;s icon works: the site you are on, one switch that turns takeover off for it, and the button that opens the full player. The icon only stops to ask where there is something to ask about — on a page with nothing to take over it opens the player directly, as before. Turning it off for a site reloads the page, because the site&#39;s own <code>&lt;video&gt;</code> elements were replaced and a reload is what hands them back.</p></li><li><p><strong>A site that embeds <code>&lt;movi-player&gt;</code> itself now gets CORS from the extension too.</strong> That site&#39;s player asks for the bytes, the host that serves them sends no header, and the player falls back to the browser&#39;s <code>&lt;video&gt;</code> — the thing the site embedded it to avoid. The same headers the takeover asks for are now offered for the URLs a page-owned player declares, whether or not takeover is switched off for that site.</p></li><li><p><strong>Restyle the chrome with <code>::part()</code>, and replace the loading ring.</strong> Forty-five parts — every bar button (<code>::part(button)</code> hits them all), the progress track, the time, the centre button, the title bar, the poster, the OSD, caption lines and the spinner&#39;s box. <code>&lt;div slot=&quot;spinner&quot;&gt;</code> swaps the built-in ribbon for your own while the player still decides when it is up and where it sits; <code>controlslist=&quot;nospinner&quot;</code> takes the ring away entirely and leaves <code>is-buffering</code> / <code>is-spinner-pending</code> on the host for a page drawing its own. <code>::part(error-screen)</code> and <code>::part(subtitle)</code> were documented but missing from the markup — they exist now.</p></li><li><p><strong>Every icon can be replaced</strong>: <code>setIcon(&quot;play&quot;, &quot;&lt;svg&gt;…&lt;/svg&gt;&quot;)</code>, <code>null</code> to restore. All 72 marks have names now (<code>MoviElement.iconNames</code>) — including the &quot;Nothing to Play&quot; and error-screen card stacks — and one swap changes the bar, the centre button, the menu and the OSD together. 27 marks that lived inline at a single call site moved into the symbol table to get there — the only drawing left outside it is the loading ribbon, which has a slot instead — and <code>::part(icon)</code> reaches every one for size and colour.</p></li><li><p><strong><code>data-movi-ignore</code> keeps a <code>&lt;video&gt;</code> native</strong> — on the element or an ancestor, the upgrade and the extensions&#39; takeover leave it alone.</p></li><li><p><strong>Renewed links keep your place</strong> — with <code>resumekey</code> unchanged across a <code>&lt;source&gt;</code> swap, the player treats it as the same media under new URLs and keeps the position, paused/playing state and speed instead of restarting from 0:00.</p></li><li><p><strong>&quot;This media needs about N Mbps to play&quot;</strong> — under <code>smoothwarning</code>, a stall caused by the link (not the device) names the rate the media needs and the rate it is arriving at. The event carries <code>link: true</code>, <code>neededBps</code>, <code>measuredBps</code>.</p></li><li><p><strong>The extensions&#39; takeover reaches into frames.</strong> A video inside an iframe — the usual shape of an embed — is taken over as well as one in the page itself. A site switched off in the popup stays off in its frames too, since the switch names the tab&#39;s site. Inside a frame the player keeps to the frame, and a video file opened on its own fills the window the way the browser&#39;s own viewer did.</p></li><li><p><strong><code>player</code> is public.</strong> The element&#39;s <code>MoviPlayer</code> is readable as <code>element.player</code>, for the core API the element does not forward — <code>getPreviewFrame()</code>, <code>getMediaInfo()</code>, <code>getCacheStats()</code>. It is replaced on every source, so read it after <code>loadeddata</code> rather than keeping it.</p></li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><p><strong>The WASM module compiles once and is instantiated many times</strong> — a second player, the preview pipeline, and a post-quality-switch rebuild no longer each pay for their own fetch and compile.</p></li><li><p><strong>Adaptive load-shedding can lift again</strong>: the frame-rate cap for underpowered devices used to engage and never release; it now retests and lifts itself on a sustained healthy stretch.</p></li><li><p><strong>A speed change no longer costs a stall</strong>: already-scheduled audio is re-stretched in place instead of thrown away for a fresh demuxer seek.</p></li><li><p><strong>Auto (adaptive) quality</strong>: fixed a unit bug that read the link estimate 8x too small, a bottom-rung confirm pass that never ran, an ignored persisted link measurement, and a climb into 8K priced off a different stream&#39;s throughput.</p></li><li><p><strong><code>/embed</code> runs inside the embedding page&#39;s own origin</strong> now (a <code>srcdoc</code> iframe) instead of a cross-origin frame that needed CORS headers a host may never send; an old embed explains what happened and offers a one-copy replacement.</p></li><li><p>Built against <strong>FFmpeg 9.0.2</strong>.</p></li><li><p><strong>The loading spinner waits before it appears</strong>: <code>spinnerdelay</code> defaults to <code>&quot;1 2&quot;</code> (a stall after 1s, an opening after 2s) instead of <code>0</code>, so a fast local open never flashes a ring. <code>spinnerdelay=&quot;0&quot;</code> restores the old behaviour.</p></li><li><p><strong>The audio strip keeps its controls</strong>: the strip IS the player, so it no longer thins out at rest, and its title row starts on the same line as the controls under it.</p></li><li><p><strong>Fullscreen ends when the source turns out to be sound alone</strong> — a bar or a sleeve in the middle of a black screen is not what fullscreen was entered for.</p></li><li><p><strong>The settings panel closes on a press anywhere outside it</strong>, like the other popups — including a press on the picture, which now dismisses it and nothing else.</p></li><li><p><strong>The adaptive decode ceiling lasts the session</strong>, not the life of the device.</p></li><li><p>The three browser extensions are now called <strong>MoviPlayer</strong>.</p></li><li><p><strong>The takeover looks before it leaps</strong>: the link a <code>&lt;video&gt;</code> declares is checked for actual media before the element is replaced, per element rather than per page, so a page whose <code>&lt;video&gt;</code> points at an HTML error page or a dead link keeps the player it had.</p></li><li><p><strong>The takeover no longer switches <code>resume</code> on.</strong> A resume prompt is something a site asks for; arriving over someone else&#39;s player uninvited is not.</p></li><li><p><strong>The next range is fetched while the current one arrives</strong> (at its halfway point), hiding each response&#39;s round trip and slow start: 1.88 → 2.12 MB/s delivered on a 2.3 MB/s link.</p></li><li><p><strong><code>smoothwarning</code> speaks from measurement at 1x too</strong>: 5 bad seconds out of 8 (under 75% of the frames) raise it once per source; the &quot;Play at 1x&quot; hint counts the same way. Seconds the host page starved the main thread don&#39;t count.</p></li><li><p><strong>The software-decode budget scales with the machine&#39;s cores</strong> (600M px/s per 8 threads) instead of one flat figure that warned about files a fast desktop plays perfectly.</p></li><li><p><strong>A script&#39;s <code>play()</code> with no gesture is treated as autoplay</strong>: a refused sound falls back to muted with &quot;Tap to unmute&quot;, and a page-muted start shows the pill.</p></li><li><p><strong>An autoplay source opens without raising the controls</strong> on <code>src</code> set or change.</p></li><li><p><strong>Auto aims at the rung the link carries</strong> and probes that rung itself; a refused reading aims the next tick lower, a two-rung jump needs two readings, and a thin buffer still climbs one rung at a time.</p></li><li><p><strong>Picking Auto goes straight to the link&#39;s rung</strong>, as a fresh open does.</p></li><li><p><strong>A downshift is decided at half the buffer</strong>, with one short probe, so the switch can prime under a picture still playing.</p></li><li><p><strong>A rung whose in-place climb cannot be primed</strong> is left out of the climb for 30s, then 60s, then at most 120s.</p></li><li><p><strong>The loading light flows like a tide.</strong></p></li><li><p><strong>Captions sit on the picture, not on the player&#39;s bottom edge</strong>: on a letterboxed picture the default place and <code>--movi-sub-bottom</code> are measured from the picture&#39;s own bottom and height, not the black bar below it.</p></li><li><p><strong>The seek track is easier to hit.</strong> Every seek listener was on the 4px track itself, so seeking meant landing on a hairline. An invisible band now reaches 18px above it and down to the button row: a press there seeks, and hovering there thickens the track. While the bar is hidden the band takes nothing, so a click low on the picture is still a click on the picture.</p></li><li><p><strong>A small player&#39;s settings popup has a close button for a mouse.</strong> On a player 480px wide or less the panel covers the gear that opened it, and on a short player nearly the whole frame. With a mouse, a round × now floats above it; touch keeps its grabber and swipe.</p></li><li><p><strong>A site&#39;s player skin no longer flashes before the takeover.</strong> The extension hides a JW, video.js or Plyr skin&#39;s poster and controls from the start of the page, and gives them back once the video is taken over, turns out to be a stream, or 4 seconds pass — and at once when the page will not be taken over at all.</p></li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p><strong>The opening poster no longer fades up out of black.</strong> It was faded in over 220ms on every load, and both the host and the canvas are opaque black before the first frame — so what the fade actually did was ramp a thumbnail out of black on every navigation, measured at opacity 0 to 1 across 158ms to 366ms. That reads as a flash, and it lasted as long as the fade rather than as long as the load. It now cuts to the poster, and the fade is kept for the case it was written for: a poster replacing a picture that is already on screen.</p></li><li><p><strong>A prefetched start no longer re-downloads the head it just read.</strong> The pre-play probe reads the head of the rung it is about to open and hands those bytes to the source so it does not fetch the same range again — except when the body came from the browser&#39;s cache, where it returned before the handover and the bytes were dropped. Measured on a prefetched open: the probe read the head in 23ms, threw it away, and the open then sat waiting for data for 129ms of a 345ms start.</p></li><li><p><strong>A seek-bar preview no longer keeps downloading after it is on screen.</strong> A hover on a stretch that has not been fetched pulls a 2MB window so a drag&#39;s next positions are already in hand, and the picture needs only its first few tens of KB — but the rest kept arriving for nobody once the pointer stopped: measured at 12 Mbit, the preview was up 0.12s into its request and 1.9MB followed over the next 1.5s, four seconds&#39; worth on a 4 Mbit link. The window now stops half a second after the pointer comes to rest, or as soon as the card closes, keeping what has arrived. The seek bar decides it rather than the player, because mid-drag it holds requests back for up to 1.5s on purpose; a drag still fetches exactly as before (the same 2 windows and 7 pictures over the same scrub).</p></li><li><p><strong>A file whose audio ends before its picture now plays to the real end</strong> instead of stopping dead where the sound ran out; also fixed a finished soundtrack read as &quot;starving&quot;, a hang seeking into that tail, and a leftover pre-seek frame dragging playback backward.</p></li><li><p><strong>Faster seeking on long-GOP sources</strong>: a seek can land on the keyframe ahead of its target instead of always decoding forward from the one behind it, cutting a 1.2s seek to under 200ms on an 8K60 file.</p></li><li><p>A <strong>paused seek that&#39;s then played</strong> no longer jumps the picture forward and never heals; a <strong>seek-bar click</strong> no longer restarts playback twice; a seek held open by a <strong>blocked autoplay</strong> no longer freezes the picture with nothing to explain it.</p></li><li><p><strong>Audio-gain glitches after a seek</strong>: a fade/duck race that could park the volume near zero with no way back except reload, now caught by a watchdog that restores the master gain without fighting a fade already in progress.</p></li><li><p><strong>Software-decoded audio</strong> (TrueHD/DTS, etc.) now hands off PCM in ~150ms blocks instead of multi-second ones, so a speed change no longer leaves old-speed audio playing under an already-changed picture.</p></li><li><p><strong>Context-menu submenus</strong> could fail to open on click, flash a stray panel, or reappear after their menu had closed — all from the same portal bookkeeping, fixed together.</p></li><li><p><strong>Seek-bar and thumbnail previews</strong>: scrubbing no longer waits for the pointer to stop, a far hover reuses a Matroska&#39;s own index instead of re-bisecting the file, the first HTTP hover reuses bytes already downloaded, and <code>thumb=&quot;precise&quot;</code> no longer gives up part-way through a long GOP.</p></li><li><p><strong>Auto quality</strong> no longer collapses the whole ladder over a stall the player caused itself, and drops a rung before blaming a link that&#39;s still delivering.</p></li><li><p>A <strong>missing container duration</strong> now gets a second, unhurried scan after load instead of settling for &quot;0:00&quot; with a dead seek bar.</p></li><li><p><strong>Mobile paste-a-link flow</strong>: more room for the field, a properly sized/centred Play button, and a bar thinned to phone proportions.</p></li><li><p><strong>Native-<code>&lt;video&gt;</code>/HLS-DASH-fallback</strong>: event parity with a real <code>&lt;video&gt;</code> (<code>play</code>/<code>pause</code>/<code>seeking</code>/<code>seeked</code>/<code>paused</code>), no volume control on a source with no audio, and a message when the browser silently drops audio it can&#39;t decode.</p></li><li><p><strong>Open-GOP (CRA/BLA) streams and transport-stream seeks</strong>: a string of decoder-queue, reference-chain and reorder-tail fixes.</p></li><li><p>A control capsule could get permanently marked &quot;empty&quot; by a measurement taken while the bar was hidden.</p></li><li><p><strong>DASH sources</strong>: an audio track no longer lists once per bitrate rendition, dash.js&#39;s own thumbnail track is read, and a preview is no longer promised on a source that can&#39;t produce one.</p></li><li><p><strong>A discarded tab comes back where it was</strong>: after Chrome&#39;s Memory Saver reloads a background tab, the position, play state and speed are restored (URL sources, Chromium).</p></li><li><p><strong>No freeze a moment after playback starts</strong>: frames decoded while leaving buffering were being thrown away (a 1.1s hole on a 1080p30 file).</p></li><li><p><strong>No freezes at slow speeds</strong>: drift budgets that were 4× too loose at 0.25x, a speed change made while paused, and a read-ahead trim that cut a GOP.</p></li><li><p><strong>No hitch at a speed change on Bluetooth</strong>: the picture was waiting out the headset&#39;s full output latency (~250ms) at every change.</p></li><li><p><strong>A video-only file&#39;s picture no longer waits for sound that never comes</strong> — a 560ms hold after every loop turn.</p></li><li><p><strong>No spinner over a picture that never stopped</strong>, after a backward seek or a loop turn.</p></li><li><p><strong>Seek-bar hover right after a resume</strong> is fast on large remote files (it took 4–7s).</p></li><li><p><strong>A video-only file in a background tab</strong> plays its tail out instead of ending early.</p></li><li><p><strong>A source with no picture shows its captions</strong> — sound-alone and data-saver audio-only ran the caption clock off a renderer that was not running.</p></li><li><p><strong>A hover on an 8K film no longer stops the page</strong>: the preview decodes at preview size instead of the source&#39;s, and gives up cleanly rather than hanging. Thumbnails fill their box instead of sitting letterboxed in it.</p></li><li><p><strong>An audio track whose link dies says so</strong> instead of leaving the picture running in silence while the reader retried every frame.</p></li><li><p><strong>A cover-art player&#39;s menus are no longer clipped</strong> by the bar&#39;s collapse, and the spinner keeps its size and place.</p></li><li><p><strong>An ordinary film no longer wears the HDR film&#39;s colour.</strong> After an HDR source, a plain one played greyish and flat: the canvas kept the wide-gamut tag the HDR pipeline set and nothing put it back for SDR.</p></li><li><p><strong>Subtitles in the audio strip.</strong> A sound-only source showed no captions at all — not an embedded track, not an SRT the viewer picked. They now appear in a band above the bar that grows for a second line and no further, centred, and the size and colour settings reach them like anywhere else.</p></li><li><p><strong>Coming back to a spot you already looked at no longer reloads it.</strong> A second hover on the same part of the seek bar re-fetched and re-decoded a picture that was already in hand.</p></li><li><p><strong>A flush that times out no longer throws away everything it was draining</strong> — 645 decoded frames, on an EOF flush that ran out of a budget fixed at 5 seconds regardless of how much was queued.</p></li><li><p><strong>A stream whose URL never admits to being one</strong> now plays: an HLS link with no <code>.m3u8</code> in it is recognised from what the server says it is serving.</p></li><li><p><strong>A poster the host refuses to share</strong> is fetched again without CORS rather than left blank; it is a picture, and nothing reads its pixels.</p></li><li><p><strong>Re-stating the source it already has</strong> — a host or a framework writing the same <code>src</code> back — no longer restarts the film from the top.</p></li><li><p><strong>JW Player&#39;s skin comes down properly</strong>, poster and all, and the poster a video.js or Plyr skin was showing carries over to the player instead of leaving a black box.</p></li><li><p><strong>A video the page had centred stays centred</strong> after the takeover, instead of jumping to the left edge.</p></li><li><p><strong>The player&#39;s corners no longer escape the frame it sits in</strong> on the web app.</p></li><li><p><strong>A divider no longer strands itself</strong> at the end of a capsule when native fallback leaves nothing visible beside it.</p></li><li><p><strong>The adaptive quality probe stops reading its own cache</strong>: a measurement answered from bytes it had already fetched could only ever say &quot;faster&quot;, so the ladder could climb on a link that never carried it.</p></li><li><p><strong>Auto quality on 4K/8K no longer sticks after a switch</strong>: a switch seeked a demuxer over a read still in flight and played from a wedged pipeline (once a 35s freeze). Manual picks were never affected.</p></li><li><p><strong>A remembered link speed that failed is lowered</strong>, so a stale record no longer opens every load on 8K.</p></li><li><p><strong>A video-only file on a slow link keeps its clock on the picture</strong> instead of running the bar over a frozen frame.</p></li><li><p><strong>Running out of data near the end is a stall</strong>, not silence plus a desync seek; and a file on a slow link no longer ends 0.25s early.</p></li><li><p><strong>An upgraded <code>&lt;video autoplay&gt;</code> starts at once</strong> when sound is certain to be refused, instead of ~1.6s under a play button.</p></li><li><p><strong>The link-speed notice</strong> probes with the source&#39;s headers (Drive answered 403) and no longer mistakes a starved link for a slow device.</p></li><li><p><strong><code>setIcon()</code> with the same icon is a no-op</strong> instead of a repaint on every framework render.</p></li><li><p><strong>8K no longer drops to 4K every few seconds</strong> on a link that carries it: a full buffer window holds the download instead of ending it.</p></li><li><p><strong>The buffer bar no longer slides back after a seek</strong>, and <strong>pausing, scrubbing and pressing play no longer empties it</strong>.</p></li><li><p><strong>A picture waiting for its bytes is not read as decode-bound</strong>, so 8K is not capped for the session.</p></li><li><p><strong>Safari no longer bars 1440p AV1</strong> on WebKit&#39;s <code>decodingInfo</code> answer when <code>VideoDecoder</code> can decode it.</p></li><li><p><strong>An abandoned quality switch stops downloading</strong>, and <strong>a link too fast to time is still measured</strong>.</p></li><li><p><strong>A downshift on a slow link finishes</strong>; <strong>a refused (403) source no longer walks the quality down</strong>; <strong><code>bindav</code> holds</strong> when the picture has not arrived.</p></li><li><p>No starved rescue over smooth playback; a held arrow key wins over an automatic switch; setting the same source twice opens it correctly.</p></li><li><p>A paused video restored in place shows no first-play button, poster or 0:00; tap to unmute shows no spinner; Matroska files no longer hitch a few seconds in.</p></li><li><p><strong>A takeover behaves like the <code>&lt;video&gt;</code> it replaced.</strong> A player skin attaches its listeners the moment it builds its <code>&lt;video&gt;</code>, before the takeover can see them, so it never heard the player play: JW reported &quot;paused&quot; for the whole film. A site that waits for JW&#39;s <code>play</code> event — one arms a 15-second &quot;ad stuck&quot; timer on every ad break — then rebuilt the player and sent the film back to 0:00. Media events now reach those early listeners; the hidden element answers health and geometry questions (<code>networkState</code>, <code>played</code>, <code>getVideoPlaybackQuality</code>, <code>getBoundingClientRect</code>, …) from the player; <code>setAttribute(&quot;src&quot;)</code>, fullscreen (the <code>webkit*</code> pair included) and picture-in-picture events go through; and a page&#39;s <code>timeupdate</code> comes at a <code>&lt;video&gt;</code>&#39;s pace rather than every frame. With site access, the extension also moves the listeners and Intersection/ResizeObservers a page attached before the takeover.</p></li><li><p><strong>A skin switching quality behind the player no longer restarts it.</strong> A new <code>src</code> for another rung of the ladder, a <code>load()</code> that asks for nothing new, and the seek back that follows used to reach the player as a new film, from the start. The rungs are the player&#39;s own quality menu now.</p></li><li><p><strong>One click, one toggle on a taken-over page.</strong> A page&#39;s own click handler on the video answered the same click the player did, so playback paused and started straight back. The layers a page leaves over the player — a big play button, a transparent click-catcher, JW&#39;s idle overlay — are hidden so clicks reach it.</p></li><li><p><strong>Seek previews survive a preview rung that will not open.</strong> Previews are read from the ladder&#39;s smallest rung, and when that file failed (another host, a missing header, an expired link) every retry went at the same file, then previews were switched off for the rest of the video. The rung is tried twice, then previews come from the rendition on screen. The extension also now asks for the CORS header on every rung of a taken-over player, not only the one it opened on.</p></li><li><p><strong>The extension&#39;s CORS rules hold when several frames ask at once.</strong> Each frame&#39;s request rebuilt the tab&#39;s rules and could remove another frame&#39;s, and a service worker woken from sleep could fail the whole update on a rule id it had forgotten.</p></li><li><p><strong>The web app&#39;s compare page shows its stats in Safari.</strong> It waited on the native pane&#39;s <code>play()</code>, which Safari can leave unsettled.</p></li><li><p><strong>Hardware decoding comes back after a software fallback.</strong> The periodic retry judged restart points by the first NAL in a keyframe packet, so a stream whose keyframes lead with an AUD/SPS/SEI never looked like one and stayed on the software decoder until a reload. The retry now trusts the demuxer&#39;s IDR classification and walks the packet to its first slice — and spends none of its capped attempts on the open-GOP keyframes hardware already refused once. When the picture is on the software decoder and stutters, the <code>smoothwarning</code> notice now says that — &quot;This video switched to software decoding&quot; — instead of blaming the device, and its event carries <code>software</code> and <code>softwareReason</code>.</p></li><li><p><strong>The web app&#39;s light theme keeps the phone header height.</strong> The under-640px rule named only the dark selector, so on a phone the light theme&#39;s header stood 12px taller over the same page.</p></li></ul><h2 id="_0-4-0-2026-08-15" tabindex="-1">[0.4.0] - 2026-08-15 <a class="header-anchor" href="#_0-4-0-2026-08-15" aria-label="Permalink to &quot;[0.4.0] - 2026-08-15&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Custom controls API</strong>: <code>addControl()</code> lets a host add its own buttons and context-menu rows — described once (icon, label, toggle/button, which side/anchor it sits on) and the element builds both faces and keeps them in sync. Controls can open nested submenus (any depth), take a hotkey that shows up in the Keyboard Shortcuts panel and flashes the OSD, group into a bar capsule of their own, and declare <code>media: &quot;video&quot; | &quot;audio&quot; | &quot;both&quot;</code> so they hide themselves for content they don&#39;t apply to. <code>anchors: { bar, menu }</code> places a control differently per surface, and an anchor can be a list for a neighbour that only sometimes exists (HDR, captions, audio track). <code>showOverlay()</code> / <code>updateOverlay()</code> / <code>hideOverlay()</code> put a host&#39;s own panel (end screen, up-next) over the picture, including in fullscreen.</li><li><strong>Host-supplied error screen</strong>: <code>part=</code> on every piece of the built-in error overlay for restyling, a <code>slot=&quot;error&quot;</code> for replacing it outright, and an <code>errordisplay</code> event (plus <code>errorTitle</code>/<code>errorMessage</code> properties) carrying the exact wording on screen — separate from the raw <code>error</code> event — including format/codec failures that never raise a runtime error. Bridged through the React/Vue/Svelte wrappers.</li><li><strong>Settings-change events</strong>: <code>aspectchange</code>, <code>loopchange</code>, <code>stablevolumechange</code>, <code>hdrchange</code>, <code>ambientchange</code>, <code>rotatechange</code>, and <code>audioonlychange</code> now fire so a host can persist a viewer&#39;s choice the way it already could for quality and volume.</li><li><strong>External chapters</strong>: a <code>chapters</code> attribute/property accepts a chapter list from outside the media file (<code>[{title, start, end?}]</code>) for sources — YouTube-style watch pages, a CMS — that never carry chapter atoms in the container itself. Supplied chapters win over the container&#39;s and survive a quality-switch/error player rebuild.</li><li><strong>Granular <code>fastseek</code></strong>: the attribute now takes a value naming which skip affordances to turn on — <code>buttons</code>, <code>keys</code>, <code>gestures</code> (plus aliases like <code>touch</code>/<code>keyonly</code>) — instead of switching on all three at once, so a page can offer just the double-tap gesture, or just the arrow keys.</li><li><strong><code>titlemode</code></strong>: controls where the title bar shows (<code>fullscreen</code>, <code>windowed</code>, <code>both</code>, <code>back</code>, <code>back-mobile-fullscreen</code>) and whether it carries a back arrow, which fires a cancelable <code>back</code> event for the host to handle. Comes with a new <code>exitFullscreen()</code> method covering all three fullscreen routes.</li><li><strong><code>themecolor</code> takes a secondary colour</strong> (<code>themecolor=&quot;#8B5CF6 #22D3EE&quot;</code>), used for the centre play/pause flash; a single colour still works exactly as before.</li><li><strong><code>cropbars</code></strong>: strips real letterbox/pillarbox padding baked into the source pixels (a 2.39:1 film in a 16:9 frame, a phone clip in a 4:3 frame) before applying <code>cover</code>/<code>fill</code>/<code>zoom</code>, instead of scaling the bars along with the picture. Detected automatically per source with a conservative brightness/duration check so a genuine dark scene or fade-to-black is never mistaken for a bar.</li><li><strong>Karaoke subtitles get a per-line backdrop and scroll on wrap</strong>: each line of a rolling WebVTT cue now has its own sized pill instead of one box squared to the widest line, and a line pushed up by a wrap slides into place the way YouTube&#39;s rolling captions do, instead of jumping.</li><li><strong>Full native media API surface</strong>: all 78 <code>HTMLMediaElement</code>/<code>HTMLVideoElement</code> members now answer, including <code>buffered</code>/<code>seekable</code>/<code>played</code>, <code>textTracks</code>/<code>audioTracks</code>/<code>videoTracks</code>, <code>srcObject</code>, <code>canPlayType</code>, <code>captureStream</code>, <code>getVideoPlaybackQuality</code>, <code>requestVideoFrameCallback</code>, <code>setSinkId</code>, <code>fastSeek</code>, and the <code>abort</code>/<code>suspend</code>/<code>encrypted</code>/<code>waitingforkey</code>/<code>cuechange</code> events — so code written against a native <code>&lt;video&gt;</code> has nothing left to reach for that isn&#39;t there.</li><li><strong>Firefox extension</strong>: the same player-in-a-tab experience as the Chrome extension, sharing its UI (popup, content script, player page) via a build step so there is one codebase to maintain, not two that drift.</li><li><strong><code>backgroundplay</code></strong> now actually keeps a phone playing when the tab is hidden (previously only had an effect on desktop browsers).</li><li><strong>Visitor feedback wall</strong> on the landing page&#39;s FAQ — a note plus an optional 1-5 star rating, with server-side abuse filtering and rate limiting.</li><li><strong>HLS/DASH streams the browser can&#39;t decode now play anyway</strong>: when Shaka/hls.js/dash.js can&#39;t decode a stream&#39;s codec (e.g. Safari rejecting HE-AAC, or an unsupported video codec), playback now escalates through the other MSE engine and, as a last resort, falls back to the player&#39;s own FFmpeg-WASM software demuxer — for both DASH and HLS. Quality switching, alternate audio-language tracks, and subtitle/caption tracks (WebVTT and TTML) all carry over into that fallback mode.</li><li><strong>Seamless, in-place quality switching everywhere</strong>: manual and automatic quality changes — across the WASM-demuxer fallback, multi-file quality sources (one file per resolution), and now HLS/DASH — swap the active rendition in place instead of tearing the player down and reloading, so there&#39;s no loading gap, no dropped playhead, and no dead silence. The incoming rendition&#39;s decoder also runs ahead of the swap point, so a quarter-second of decoded frames is already ready the instant the old rendition&#39;s queue is retired — no frozen frame sitting under the spinner for as long as a fresh keyframe takes to arrive.</li><li><strong>Auto (adaptive) quality</strong>: an &quot;Auto&quot; option that measures your link&#39;s throughput and picks the best rendition it can sustain, now available on the demuxer-fallback and multi-file quality-source paths too, not just HLS/DASH. It runs a short pre-play speed test past a CDN&#39;s caching/pacing burst and opens directly on the rung the link can sustain, rather than climbing one rung at a time or trusting a stale cross-video estimate — so no opening 1080p on a 0.7 Mbps link, and no visible ramp up from 144p on a fast connection. Upshifts are confirmed by probing the target rung, so a burst can only make the decision <em>more</em> conservative; rungs are barred by codec <em>and</em> height together (a failed 4K AV1 rung no longer poisons 4K H.264 too); decode cost is priced by width × height × fps × codec factor instead of by height alone; the software-decode ceiling is sized separately per codec and no longer caps a healthy hardware 1080p session at 480p; and a codec that can&#39;t be hardware-decoded at all switches to software after one failed rung instead of walking the whole ladder down first. It persists your Auto preference across videos and shows the active rung like &quot;Auto (1080p)&quot;. Also fixed along the way: thrashing between rungs, downshifting on estimate noise instead of an actually-draining buffer, losing a voluntary upshift while the tab is hidden, and switching quality mid-seek — which could corrupt the demuxer and desync audio/video by tens of seconds.</li><li><strong>Pluggable <code>SubtitleRenderer</code> for ASS/SSA</strong> (issue #17): a host hook to plug in a custom subtitle renderer (e.g. jassub/libass-wasm) for full ASS/SSA styling — positioning, karaoke, embedded fonts — since the player&#39;s canvas-only pipeline can&#39;t use a native <code>&lt;track&gt;</code> overlay for these.</li><li><strong><code>fallback=&quot;native&quot;</code></strong>: when the WASM/WebCodecs pipeline can&#39;t read a source (a no-CORS cross-origin file, a transient network failure), playback now hands off to the browser&#39;s own <code>&lt;video&gt;</code> element wrapped in the player&#39;s own controls, instead of a dead end. The degraded surface keeps more than the transport: a <code>&lt;source&gt;</code> quality ladder still switches in place — with an Auto mode measured by stall rate rather than buffer depth, since a native element decodes opaquely and its buffer reads as permanently starved by the usual rule — <code>&lt;track&gt;</code> subtitles are parsed and painted into Movi&#39;s own overlay so the subtitle styling and delay controls keep working, and split video+audio sources, which a lone <code>&lt;video&gt;</code> can&#39;t play at all, get a synced companion <code>&lt;audio&gt;</code>: mirrored transport, drift correction, and a hard resync when the two disagree, including multi-language audio switching.</li><li><strong><code>engine</code> attribute</strong>: choose which playback engine leads and what follows it — <code>wasm</code> (Movi&#39;s demuxer + WebCodecs, and for a manifest its own DASH/HLS handling), <code>shaka</code>, <code>dashjs</code>, <code>hlsjs</code>, <code>native</code>. A space-separated list, first name first: <code>engine=&quot;native wasm&quot;</code> plays through the browser and only falls back to Movi&#39;s pipeline, <code>engine=&quot;dashjs shaka&quot;</code> prefers dash.js for manifests. Unset keeps the built-in order.</li><li><strong>Pluggable URL-scheme adapter registry</strong>: <code>registerSourceAdapter()</code> teaches the player about custom <code>src</code> schemes — <code>s3://</code>, <code>ipfs://</code>, <code>ws://</code>, etc. — with no per-element wiring.</li><li><strong>Adaptive load shedding for underpowered devices</strong>: a detector measures the achieved frame-present rate against the source&#39;s rate and sheds load on a sustained deficit, so a device that can&#39;t keep up (low-end mobile on 4K, software-decoded AV1) degrades gracefully instead of stuttering indefinitely.</li><li><strong><code>movi-player/element/slim</code></strong>: a second, smaller build (4.2MB of JS vs. 11.4MB) that streams the FFmpeg WASM from a separate <code>movi.wasm</code> file instead of embedding it, with automatic fallback to native playback if the WASM can&#39;t be fetched. The framework wrappers have slim twins too — <code>movi-player/react/slim</code>, <code>movi-player/vue/slim</code>, <code>movi-player/svelte/slim</code> — same components, props, and events, and <code>wasmurl</code> points the loader at wherever you host the <code>.wasm</code>.</li><li><strong>Standard <code>HTMLMediaElement</code> events</strong>: ten previously-missing standard events — including <code>seeking</code>/<code>seeked</code> and <code>durationchange</code> — now fire, so code ported from a native <code>&lt;video&gt;</code> works without changes.</li><li><strong>Full IDL property reflection</strong>: every documented attribute (all 57) can now be read and set as a JS property (<code>el.rotate = 90</code>), not just via <code>setAttribute</code>/<code>getAttribute</code>.</li><li><strong>Declarative <code>rotate</code> attribute</strong> (<code>0</code>/<code>90</code>/<code>180</code>/<code>270</code>): set rotation from markup instead of only through the hotkey/menu.</li><li><strong><code>version</code> exposed at runtime</strong>: <code>MoviElement.version</code> (static) and <code>el.version</code> (instance), jQuery-style. Alongside it, <code>MoviElement.build</code> / <code>el.build</code> (and the <code>BUILD</code> export) report which bundle is running — <code>&quot;slim&quot;</code> or <code>&quot;full&quot;</code> — since the two are otherwise indistinguishable at runtime despite loading the engine differently. The stats panel leads with both: <code>Player: 0.4.0 (slim)</code>.</li><li><strong>Framework wrappers type all 57 attributes</strong>: React/Vue/Svelte wrappers now type the complete attribute set and accept typed <code>&lt;source&gt;</code>/<code>&lt;track&gt;</code> children (<code>height</code>, <code>srcLang</code>, <code>kind=&quot;audio&quot;</code>, etc.) instead of needing string/attribute-spread workarounds.</li><li><strong>VS Code IntelliSense for <code>&lt;movi-player&gt;</code></strong>: attribute and value completion with hover docs, plus CSS completion for the 38 <code>--movi-*</code> theme variables.</li><li><strong>Examples gallery</strong> (<code>/examples</code>): a page of live, copy-paste <code>&lt;movi-player&gt;</code> recipes with modal demos; existing recipes expanded and reorganized into themed sections, including a new ASS/SSA subtitle recipe.</li><li><strong>Embed-code dialog</strong>: a toggle-driven dialog (autoplay, muted, loop, thumbnails, resume, ambient glow) generates a live <code>/embed</code> snippet, replacing the old one-shot copy button; <code>/embed</code> itself is now restricted to framed contexts, with a branded block page when opened directly.</li><li><strong>Google Drive video player</strong> (<code>/drive</code>): sign in, pick a video from your Drive, and stream it straight into <code>movi-player</code>.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Every setting moved behind one gear</strong>: quality, speed, stable volume, aspect, loop, audio track and HDR used to each have their own button on the bar; now there&#39;s a single gear panel the way most other players do it, and the bar keeps only what you touch <em>while</em> watching (play, volume, time, captions, PiP, fullscreen). Rows appear only when they lead somewhere, track rows now name the language (&quot;HIN · Surround&quot;) instead of just the channel layout, and picking a value closes the panel while toggles don&#39;t.</li><li><strong>Control bar redesign</strong>: buttons group into capsules, chapter breaks are real gaps cut through the whole progress bar (groove, buffer and fill all break together) rather than ticks painted over it, the bar sits closer to the frame edge with a thicker/hoverable progress track, the quality badge reads height <em>and</em> frame rate (&quot;720p@60&quot;), an HDR badge joins it, and aspect ratio moved beside the gear. The keyboard shortcuts panel now fits inside a phone-sized player instead of running off the bottom.</li><li><strong><code>bindav</code> (bind audio+video on a stall) is on by default now</strong>, opt out with <code>bindav=&quot;false&quot;</code>. Whichever of audio or video runs dry now waits for the other before either resumes, instead of the picture racing seconds ahead of frozen audio (or vice versa) on a slow link.</li><li><strong>HTTP range-request sizing tuned against a real paced CDN</strong>: opens with a 4MB chunk for a fast first byte, then fills with 8MB chunks (previously always 4MB, which spent most of a high-bitrate stream&#39;s time on per-request overhead instead of filling the buffer).</li><li><strong>The settings gear now hides rows that would silently do nothing</strong>: stable volume and aspect ratio disappear from the panel on a source playing through the native fallback or an adaptive-stream engine, where neither setting has anywhere to act.</li><li><strong>Compare page (<code>/compare</code>) now served from the slim build</strong>, and the player bundle preloads during <code>&lt;head&gt;</code> so its download starts earlier on the main app.</li><li><strong>README and docs discoverability</strong>: an honest comparison table (added dash.js and Shaka Player columns) and a new &quot;Alternatives&quot; section naming peer libraries; docs are now served under <code>/docs</code>, and a Terms of Service page was added.</li><li><strong>Third-party license attribution completed</strong> for every bundled component, including the FFmpeg LGPL notice.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Picture-in-Picture</strong>: the floating window now draws its own buffered range and loading spinner (previously both were painted on the page nobody was looking at) and renders subtitles inside the Document Picture-in-Picture window; its clock survives a change of video instead of freezing on the old one; the page&#39;s own clock, progress and controls keep running while PiP is open instead of freezing when the bar auto-hides or the tab backgrounds; the next auto-advanced video keeps painting into an already-open PiP window instead of going black, and starts directly in that window instead of waiting for the tab to be visible; the window picks up <code>themecolor</code> instead of always rendering violet; it closes automatically when the element is torn down, so no orphaned black window survives a video-to-video rebuild; and the PiP control is hidden inside any iframe, where the browser forbids opening a PiP window anyway.</li><li><strong>Firefox autoplay false-mute</strong>: Firefox flips an <code>AudioContext</code> from &quot;suspended&quot; to &quot;running&quot; about 100ms after <code>resume()</code>, after the promise has already resolved — the autoplay check read the state once, right after <code>play()</code>, and muted audio Firefox had already allowed, leaving &quot;Tap to unmute&quot; on screen for the whole video.</li><li><strong>Muted-audio semantics</strong>: pausing then pressing mute no longer shows an unmute pill as though the browser had blocked audio; unmuting a paused player no longer starts it playing over a still picture; and a deliberate mute is no longer clawed back by the same recovery path that restores audio the browser itself had blocked.</li><li><strong>Split audio+video robustness</strong>: the split-audio demuxer no longer starves during the opening speed-test burst (the opening rung is sized to leave it headroom, and a stalled open retries with backoff); a software audio-decode circuit-breaker trip now reports the failure and restores the hardware decoder that was working instead of leaving audio silent for the rest of the video; and the audio clock is rebuilt correctly after audio was dropped while suspended.</li><li><strong>Rounded corners</strong> stop eroding the outermost pixel row, and now survive fullscreen entry/exit, a quality switch, and losing/regaining the GPU context — previously several of these dropped the clip entirely or cut into the picture itself.</li><li><strong>Seek bar falsely reading &quot;fully buffered&quot;</strong>: a large MKV (cues at the tail) or an MP4 with a trailing <code>moov</code> made an opening read of the file&#39;s last few bytes look like the whole file had downloaded; the buffered bar now checks that the read window is actually near the playhead, not just that it happens to reach the end of the file.</li><li><strong>A refused byte range is now reported instead of read as end-of-file</strong>: an expired signed URL (403) used to look like the video had simply finished — clock jumped to the duration, &quot;ended&quot; fired — instead of surfacing an error; a URL that keeps refusing now backs off and stops retrying instead of firing over a thousand requests in a few seconds, and reports a message that matches the failure (expired link vs. not found vs. server error).</li><li><strong>Image subtitles</strong>: stopped re-encoding the same PGS/VobSub bitmap to a data URL on every render tick (was happening 60x/sec even when nothing had changed), and a cue that lands after a gap no longer visibly glides ~50px into position over a third of a second.</li><li><strong>Centre play/pause icon</strong>: no longer pops in-then-out when the button was already on screen (e.g. the poster); an in-flight fade is now cancelled the moment the button becomes a persistent control, fixing an occasional flicker back to full opacity; and a media-session play/pause (lock screen, media keys) now flashes the same receipt a click does.</li><li><strong>Timeline thumbnail strip</strong>: a touch device gets paging arrows again (sized for a fingertip) instead of relying on scroll alone with no sense of how much strip is left; and the scroll indicator now only draws while something is actually scrolling instead of a static grey line at all times.</li><li><strong>Context menu / settings panel agreement</strong>: both now agree on what&#39;s actually available on the current source; a tall context menu rests on the player&#39;s bottom edge instead of running past it; the aspect-ratio icon and open submenu update on every change; and the speed submenu ticks the right row regardless of what triggered the rate change.</li><li><strong>Audio-only ⇄ video transitions</strong>: the picture now rejoins before the audio-only path stops the sound for it (previously could stop cold), coming back from audio-only restores the picture instead of staying audio-only, the timeline holds correctly while the picture is gone, and a player that&#39;s been torn down stops downloading video no one will see.</li><li><strong>Legacy/unmapped codecs</strong> now fall back to software decoding instead of failing outright — WebCodecs has no registered codec string for several FFmpeg-supported legacy codecs (Motion JPEG in AVI among them), which used to leave the renderer black (#19, thanks <a href="https://github.com/Wgmlgz" target="_blank" rel="noreferrer">@Wgmlgz</a>).</li><li><strong><code>persist</code> now works when a framework mounts the element</strong>: React (and similar) set attributes <em>after</em> appending the element, so the persisted-settings restore ran before <code>persist</code> existed and silently restored nothing; it now re-runs when the attribute actually arrives.</li><li><strong>Audio-track reporting</strong>: the audio-track list is rebuilt on a source change instead of carrying over the previous file&#39;s tracks, and the reported &quot;current&quot; track now matches what&#39;s actually playing instead of what was last selected.</li><li><strong>A removed player could keep playing</strong>: a source whose load failed <em>after</em> the element was taken out of the document (a host swapping videos on navigation) built its fallback player on the detached element — the teardown had already run, so nothing could ever stop it and the old audio played on underneath the next video. Player creation now bails once the element is gone, and the audio elements a quality switch hands between players are released instead of being left running.</li><li><strong>Spurious &quot;1x&quot; / &quot;100%&quot; OSD on every playback start</strong>: restoring persisted settings re-entered the volume/speed updaters (and reflected the values back onto the attributes, re-entering again), each time flashing the OSD as if the user had just changed something. The OSD now fires only on an actual change.</li><li><strong>Karaoke subtitles printed their internal delimiter</strong>: cue text carries the full upcoming sentence after a ghost marker so the caption box can be sized to the finished line; renderers that didn&#39;t strip it (the native surface, hls.js) put the marker and the whole sentence on screen.</li><li><strong>Playback recovery instead of dead ends</strong>: the player now recovers from a corrupt/short demuxer read, a frozen frame with audio still advancing after a long backgrounded spell, a stream that&#39;s exhausted its recovery budget (now a self-healing &quot;Reconnecting…&quot; instead of a permanent error), a stuck cached WASM module after an abort, and a hardware decode error on too heavy a rendition (drops to a lower rung under Auto instead of a dead-end error overlay).</li><li><strong>Alternate audio-language and subtitle switching in HLS/DASH</strong>: audio-language pickers that didn&#39;t work at all in some paths now do; subtitle-language switches no longer leave the previous language&#39;s caption stuck on screen; duplicate same-language audio renditions no longer clutter the menu with entries like &quot;English · 48kbps / 64kbps / 32kbps&quot;.</li><li><strong>Rotation, timeline, and subtitles across stream playback</strong>: rotating a video (or resizing while rotated) is now respected during HLS/DASH/Shaka playback — it previously touched the wrong renderer and could be a silent no-op, or revert on resize.</li><li><strong>Context menu in audio-only mode</strong>: menu item queries are portal-aware everywhere now, the menu live-updates the moment you switch to audio-only, and video-only items (Aspect Ratio, Rotate, etc.) are hidden while in audio mode.</li><li><strong>HDR re-detected on quality change</strong>: a rendition ladder can mix HDR and SDR rungs (e.g. an HDR 4K rung under an SDR 1080p one) — the HDR indicator now re-evaluates on every quality change instead of sticking with whatever the first-loaded rung reported.</li><li><strong>Album art no longer flashes over a playing video</strong> during a quality switch.</li><li><strong>Seek bar and progress UI</strong>: clicking the seek bar no longer double-seeks and snaps back to the old position; ABR and the recovery watchdogs no longer fight an in-flight seek; the played/buffered bar draws seamlessly and resets to zero on a fresh load.</li><li><strong>Audio robustness</strong>: split (separate-URL) audio no longer stalls when the tab is backgrounded; audio-only mode stops downloading the unwatched video stream and correctly suppresses the &quot;Play at 1x&quot; stutter hint; the screen wake lock is now acquired on tap-to-unmute, ordered so Safari doesn&#39;t consume the gesture on the wrong request; the pitch stretcher warms up at the correct rate; stale pre-seek audio is dropped on seek instead of playing briefly.</li><li><strong>Source resiliency</strong>: a streamed source retries open-ended instead of failing when a bounded byte-range request gets a 403; file size is recovered via a ranged GET when a <code>HEAD</code> request throws (issue #14).</li><li><strong>Playback rate changes stay seek-free</strong> when a healthy audio clock can anchor them, instead of always reseeking.</li><li><strong>Google Drive sign-in</strong> no longer pops up unbidden on page load — it now only triggers on an explicit click.</li><li><strong>Chrome extension no longer tags the page DOM</strong> for presence detection, which was showing up as a hydration mismatch on React/Next.js and similar pages; it now uses an in-memory window flag instead.</li></ul><h2 id="_0-3-5-2026-07-11" tabindex="-1">[0.3.5] - 2026-07-11 <a class="header-anchor" href="#_0-3-5-2026-07-11" aria-label="Permalink to &quot;[0.3.5] - 2026-07-11&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Captions rotate with the video</strong>: rotating the video (<code>R</code> / menu) turns the subtitles with it and keeps them on the rotated bottom edge — text and image (PGS/VobSub) subtitles both.</li><li><strong>Blurred backdrop for embedded album art</strong>: audio with <em>embedded</em> cover art now gets the same blurred-artwork backdrop as poster-based audio, instead of a plain dark background.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Fullscreen: the right-click / gear menu wouldn&#39;t open</strong>: the menu portals to a body-level layer to escape page clipping, but in fullscreen the player is the fullscreen element so that layer rendered outside it — the menu now stays within the player in fullscreen.</li><li><strong>Context-menu toggles didn&#39;t reflect their new state</strong>: Ambient Mode / Stable Volume / Loop / Rotate / HDR toggled from the menu now update their On/Off label and highlight (the state was written to the wrong place while the menu was portaled).</li><li><strong>Volume slider offered a 200% boost on native audio</strong>: a single external audio source plays through a native <code>&lt;audio&gt;</code> element that can&#39;t boost — the slider now caps at 100% there.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Wider context-menu submenus</strong>: audio-track and audio-output submenus are wider so long track / device names don&#39;t wrap.</li></ul><h2 id="_0-3-4-2026-07-11" tabindex="-1">[0.3.4] - 2026-07-11 <a class="header-anchor" href="#_0-3-4-2026-07-11" aria-label="Permalink to &quot;[0.3.4] - 2026-07-11&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>OS Media Session — lock-screen &amp; hardware-key controls</strong>: title metadata, artwork, and play/pause/stop/seek controls on the OS lock screen and notification shade via <code>navigator.mediaSession</code>, with a synced position scrubber.</li><li><strong>Press-and-hold to 2x (touch)</strong>: YouTube-style long-press speeds playback to 2x while held, reverts on release.</li><li><strong>Settings (gear) button</strong>: touch-friendly way to open the context menu now that long-press drives hold-to-2x.</li><li><strong>&quot;Play at 1x&quot; stutter hint</strong>: OSD nudge when a heavy source can&#39;t sustain above 1x (dropped video frames, smooth audio), with a cooldown.</li><li><strong>360°/VR seek-bar preview reprojection</strong>: seek-bar hover preview now matches your current viewing angle instead of the raw flat frame.</li><li><strong>Themeable control-bar colors</strong>: more chrome colors driven by overridable <code>--movi-*</code> CSS custom properties for embedder theming.</li><li><strong>Volume boost to 200%</strong>: the volume slider now reaches 200% (VLC-style) with a tinted boost zone above the unity mark, for quiet sources.</li><li><strong>Screen-reader accessibility</strong>: an off-screen <code>aria-live</code> region announces captions, and the seek/volume controls are now real <code>role=&quot;slider&quot;</code> widgets with spoken position text.</li><li><strong>QoE analytics (<code>movi-qoe</code>)</strong>: a versioned QoE event stream (startup, rebuffering, bitrate switches, decode-fallback, errors, heartbeats) via a DOM event, <code>addQoeSink()</code> / <code>getQoeSession()</code>, and a built-in <code>beaconSink(url)</code>.</li><li><strong>Framework wrappers + typed element</strong>: official typed <code>movi-player/react</code> / <code>vue</code> / <code>svelte</code> wrappers (subpaths of the one package — no extra install), plus <code>HTMLElementTagNameMap</code> typing for <code>&lt;movi-player&gt;</code>.</li><li><strong>Embed / headless bare player + <code>noerrorscreen</code></strong>: no <code>controls</code> attribute makes <code>&lt;movi-player&gt;</code> a pure display surface (no resume dialog, empty state, spinner, or mouse interaction); <code>noerrorscreen</code> also suppresses the built-in error overlays.</li><li><strong>Number-key seeking (<code>1</code>–<code>9</code>)</strong>: <code>1</code>–<code>9</code> jump to 10%–90% of the timeline (YouTube-style), alongside <code>0</code> / <code>Home</code>.</li><li><strong>Swipe-to-dismiss touch menu</strong>: the gear-opened context menu is a right-side drawer on touch — drag it toward the right edge to close it. Vertical scrolling and taps inside the menu are unaffected.</li><li><strong>Pinch to change aspect fit in fullscreen (touch)</strong>: a two-finger pinch switches the fit YouTube-style — spread to zoom-to-fill (crop), pinch in to fit — with the same Fit/Fill OSD. Fullscreen-only (won&#39;t fight inline page pinch-zoom); excluded from 360° mode.</li><li><strong>iOS Safari pseudo-fullscreen fallback</strong>: iOS Safari only allows element-fullscreen on <code>&lt;video&gt;</code> and the player renders to canvas — fullscreen falls back to a CSS viewport-fill mode (behind Safari&#39;s toolbars) with forced-landscape rotation for landscape video. iPad / real element-fullscreen browsers unaffected.</li><li><strong>Small-player control bar &amp; menu overhaul</strong>: usable down to ~100px wide — tighter padding/buttons below 400px, PiP folds behind the &quot;more&quot; toggle, the expanded cluster scrolls horizontally, fullscreen folds in below 290px, the resume dialog stacks instead of clipping, dropdown menus cap to the room inside the player, and the gear hides while a bottom dropdown or the timeline is open.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>HTTP streaming without cross-origin isolation</strong>: HTTP(S) sources no longer need COOP/COEP (<code>SharedArrayBuffer</code>) — single-threaded Asyncify WASM falls back to a plain-buffer path; fixes a <code>Timeout at 0</code> on pages without the headers. The headers now only enable an optional zero-copy fast-path.</li><li><strong>Fullscreen forced landscape for portrait video (Android)</strong>: the orientation lock now reads the effective display rotation, so a portrait clip stored as landscape-frames-plus-rotation stays portrait in fullscreen.</li><li><strong>Audio-strip (collapsed) mode</strong>: shortcuts work while collapsed; the gear aligns with the title, stays visible and appears on load; the touch menu no longer overflows; the strip reflows on late cover art; a strip with no <code>controls</code> hides itself.</li><li><strong>Picture-in-Picture cursor</strong>: the cursor stays visible above the controls in document PiP.</li><li><strong>Touch hold-to-2x too eager</strong>: threshold raised to 600ms and the gesture cancels when it becomes a scroll.</li><li><strong>Resume-dialog selection ring</strong>: visible on pointer devices (a global <code>outline</code> reset was hiding it), hidden on touch.</li><li><strong>Blank snapshot on hardware AV1</strong>: falls back to the decoded <code>VideoFrame</code> when WebGL read-back is blank.</li><li><strong>Settings gear on non-touch</strong>: hidden where right-click already opens the menu.</li><li><strong>Safari first-load flash</strong>: no flash of unstyled overlays on first load.</li><li><strong>OS Media Session focus</strong>: the silent audio anchor is now ≥5s so the OS grants full media-key focus.</li><li><strong>Volume clamping</strong>: native-element volume clamped to <code>[0,1]</code>; the slider caps at 100% unless boost is on.</li><li><strong>Context menu clamped on-screen</strong>: the menu repositions after opening so it never spills off-viewport.</li><li><strong>Lite / proxy browsers without cross-origin isolation</strong>: the player runs on reduced browsers with no <code>SharedArrayBuffer</code>.</li><li><strong>Open-GOP CRA-opening HEVC stuck buffering</strong>: a seek now accepts a CRA at or before the target instead of waiting indefinitely for an IDR.</li><li><strong>TrueHD/DTS buzzy/jittery audio around seeks and replays</strong>: software decoder now flushes on seek, a cold-start cushion applies on every seek/replay (not just first play), and replay no longer trips a spurious desync resync.</li><li><strong>Multi-audio-track files stalling repeatedly</strong>: unused audio streams are now discarded at the demuxer level so the active track isn&#39;t starved by interleaved packets from a track nobody&#39;s listening to.</li><li><strong>Crash on load with newer WASM builds</strong>: heap bytes are now copied out before <code>TextDecoder.decode()</code> (resizable <code>ArrayBuffer</code> heaps threw and blocked every file from loading).</li><li><strong>Playback stalling after resuming from the background</strong>: the un-throttled background decode timer now restarts on resume (including via Media Session), so audio no longer starves and video no longer jumps ahead of audio.</li><li><strong>SigV4 presigned URLs (S3 / R2 / GCS) failing to load</strong>: falls back to ranged/plain <code>GET</code> when a <code>HEAD</code> probe returns 403/401 instead of treating it as access-denied; extension link probe also recognizes presigned links without a file extension.</li><li><strong>Context-menu submenu options all showing &quot;active&quot; (touch)</strong>: Fit and Speed submenus no longer accumulate a stale highlight.</li><li><strong>Selected-track text unreadable in light theme + auto-hide stuck open</strong>: readable codec/language text in light theme; switching audio tracks restarts the auto-hide timer.</li><li><strong>VS Code extension bundle out of date</strong>: republished with the current player build (was missing the 0.3.3 audio-output/VR/FLAC fixes).</li><li><strong>VS Code: fullscreen button hidden despite fullscreen working</strong>: the webview iframe reports <code>fullscreenEnabled=false</code> (so the button auto-hid), but fullscreen works via the extension host — the webview now grants the capability so the button stays.</li><li><strong>Embed: dead fullscreen/PiP/audio-output controls no longer shown</strong>: hidden (instead of silently failing) when the embedding iframe&#39;s Permissions Policy disallows them; PiP also retires itself if opening its window throws.</li><li><strong><code>playsinline</code> now also gates touch gestures</strong>: an inline touch player suppresses swipe-seek/volume gestures so they don&#39;t fight page scroll (resumes in fullscreen). The separate <code>gesturefs</code> attribute is now deprecated (still honored).</li><li><strong>Right-click context menu clipped by page layout</strong>: the menu portals to a body-level layer so it escapes clipping ancestors (a wrapper&#39;s <code>overflow:hidden</code>) instead of being chopped at the player edge; submenus are viewport-aware in this mode.</li><li><strong>Resume-dialog selection ring didn&#39;t follow the pointer</strong>: the ring now moves to whichever button the pointer is over, matching arrow-key behavior.</li><li><strong>Scrub thumbnail previews depended on attribute order</strong>: <code>&lt;movi-player src=… thumb&gt;</code> no longer silently builds with previews disabled; order doesn&#39;t matter, and the timeline key (<code>T</code>) generates thumbnails regardless of the <code>thumb</code> attribute.</li><li><strong>Timeline panel: thumbnails touching + controls-bar flash on close</strong>: bigger thumbnail-strip gap and a smaller hover/active pop so thumbnails don&#39;t overlap on small players; closing no longer flashes the auto-hidden controls bar.</li><li><strong>360° mode: scroll-wheel accidentally zoomed the view</strong>: removed the wheel-zoom listener so page scrolling behaves normally; drag-to-look and pinch-to-zoom remain.</li><li><strong>Aspect-fit menu item didn&#39;t show the Fit/Fill OSD</strong>: changing aspect from the context menu now flashes the same OSD as the button and keyboard shortcut.</li><li><strong>Pinch-to-fit and press-and-hold-to-2x could fire together</strong>: a second finger landing cancels hold-to-2x so a pinch can&#39;t trigger 2x mid-gesture.</li><li><strong>HTTP streaming: large remote files restarted mid-playback on small out-of-window reads</strong>: served with a one-off range fetch while the main stream keeps running (fixes the request &quot;cancelling&quot; on large torbox-style files), with a cap on consecutive one-off fetches so a real seek still restarts the stream. (Thanks @anilabhadatta.)</li></ul><h2 id="_0-3-3-2026-06-29" tabindex="-1">[0.3.3] - 2026-06-29 <a class="header-anchor" href="#_0-3-3-2026-06-29" aria-label="Permalink to &quot;[0.3.3] - 2026-06-29&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Immersive / VR video (<code>vr</code> attribute)</strong>: 360° equirectangular, 180° (VR180), fisheye, side-by-side <strong>stereo (3D)</strong>, and stereographic <strong>&quot;little planet&quot;</strong> projections, rendered with a WebGL2 fullscreen-quad raycast and a spring-animated look-around camera (drag / arrow keys / pinch-zoom). Auto-enters the right projection from the source&#39;s spherical metadata — no toggle UI — or force it with tokens (<code>vr=&quot;180&quot;</code>, <code>vr=&quot;fisheye sbs&quot;</code>, <code>vr=&quot;littleplanet&quot;</code>). Opt-in on-screen joystick via <code>vrpad</code>.</li><li><strong>Audio output device selection (<code>audiooutput</code> attribute / <code>setAudioOutput()</code> API)</strong>: route playback to any system output device (speakers, Bluetooth, virtual). <code>getAudioOutputs()</code> lists devices, <code>setAudioOutput(deviceId)</code> switches — it also accepts a <strong>label substring</strong> (e.g. <code>&quot;Headphones&quot;</code>) since device ids are session-salted — <code>getAudioOutput()</code> reads the current sink, and an <code>audiooutputchange</code> event fires on change. Surfaced as an <strong>&quot;Audio Output&quot;</strong> submenu in the right-click menu (the browser asks for device permission on first use; granted hosts list devices directly). Routed through <code>AudioContext.setSinkId</code>.</li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>FLAC audio playback</strong>: FLAC now always uses the software (FFmpeg-WASM) decoder — WebCodecs&#39; FLAC decoder throws <code>EncodingError</code> on these streams and the error→software fallback didn&#39;t recover in every browser, leaving FLAC silent.</li><li><strong>Title HTML-entity decoding</strong>: titles from scraped / download-site sources that carry entities like <code>&amp;quot;</code> (and the non-standard <code>&amp;Quot;</code>), <code>&amp;amp;</code>, <code>&amp;#39;</code> now render as the real characters (<code>&quot;</code>, <code>&amp;</code>, <code>&#39;</code>).</li><li><strong>Audio-strip title placement</strong>: when an audio file <em>with a title</em> collapses to the thin control strip, the title now sits in its own row above the controls instead of overlapping the control row.</li><li><strong>Controls auto-hide vs. the timeline &amp; menus</strong>: the control bar no longer auto-hides while the <strong>storyboard timeline</strong> (<code>T</code>) is open or when clicking a thumbnail in it, and it correctly re-arms its inactivity auto-hide after the right-click menu closes.</li></ul><h2 id="_0-3-2-2026-06-17" tabindex="-1">[0.3.2] - 2026-06-17 <a class="header-anchor" href="#_0-3-2-2026-06-17" aria-label="Permalink to &quot;[0.3.2] - 2026-06-17&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Desktop app — Windows / macOS / Linux (<code>desktop/</code>)</strong>: a new Electron app wrapping the player engine. Plays MKV, HEVC, AV1 and 4K HDR locally through the same WebCodecs + FFmpeg-WASM pipeline, served from a cross-origin-isolated localhost server so the WASM demuxer keeps <code>SharedArrayBuffer</code>. Includes drag-and-drop, native <strong>Open With</strong> / file associations for every supported format, URL playback through a built-in proxy (no CORS limits), a <strong>multi-file playlist</strong> with auto-advance, recent files, an Open-URL dialog with clipboard paste, full-window keyboard shortcuts, and a <strong>native always-on-top Picture-in-Picture</strong> window (Electron doesn&#39;t render Document PiP, so PiP is a real OS window that hands the source off and resumes on return). Cross-platform installers (<code>dmg</code> / <code>nsis</code> / <code>AppImage</code> + <code>deb</code>) and document icons via electron-builder.</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Software-decoder fallback without WebCodecs</strong>: when the browser has no WebCodecs <code>VideoDecoder</code> (e.g. Firefox, especially on mobile) the player now falls back to the WASM software decoder instead of failing — video was left stuck buffering while audio fell back on its own.</li><li><strong>Seek before ready is queued</strong>: the <code>currentTime</code> setter now holds a seek requested before the player is ready and applies it on the next seekable state, so a hand-off / early seek no longer stalls on a still-loading source.</li><li><strong><code>&lt;movi-player hidden&gt;</code> now hides</strong>: the component&#39;s <code>:host { display: block }</code> was overriding the UA <code>[hidden]</code> rule, so the standard <code>hidden</code> attribute did nothing.</li><li><strong>Centre play/pause + loading spinner positioning</strong>: sit at the true centre on the initial / autoplay-off screen and lift slightly to balance the controls bar only once playback has started; they also animate in compact / PiP layouts. (Previously keyed off a <code>:host:has()</code> rule that some engines, e.g. Electron&#39;s Chromium, don&#39;t apply to shadow descendants.)</li></ul><h2 id="_0-3-1-2026-06-10" tabindex="-1">[0.3.1] - 2026-06-10 <a class="header-anchor" href="#_0-3-1-2026-06-10" aria-label="Permalink to &quot;[0.3.1] - 2026-06-10&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>MPEG-DASH playback (<code>.mpd</code>) (closes #9)</strong>: DASH manifests now play alongside HLS through the adaptive pipeline.</li><li><strong>Unified adaptive streaming via Shaka (HLS / DASH / Smooth)</strong>: Shaka is the primary engine for <code>.m3u8</code> / <code>.mpd</code> / <code>.ism</code>; hls.js and dash.js remain as automatic fallbacks. <code>DashFallback</code> plays bare-<code>BaseURL</code> manifests Shaka rejects via the demuxer.</li><li><strong>Live-stream UI</strong>: <code>LIVE</code> badge that jumps to the live edge, DVR-window seeking, Auto-mode quality badge.</li><li><strong>Custom request headers (<code>headers</code> attribute / property)</strong>: Auth tokens / signed headers across manifest + segments, progressive HTTP, thumbnails, and the encrypted source. JSON-string attribute or object property; also <code>PlayerConfig.headers</code>.</li><li><strong>Audio-only data-saver mode (<code>audioonly</code> attribute / <code>audioOnly</code> property)</strong>: Play just the audio to save CPU/bandwidth — muxed files skip the video decode, streams switch to an audio-only rendition, split sources stop downloading the video body. Live-toggleable, forces the album-art strip UI.</li><li><strong>Non-range (no-Range) server playback</strong>: Servers that ignore <code>Range</code> (<code>200</code> not <code>206</code>) now play via a forward-only sliding window (<strong>linear mode</strong>); a new <code>linearmode</code> event lets the UI adapt.</li><li><strong>MPEG-5 LCEVC decoding (<code>lcevc</code> / <code>lcevcurl</code> attributes)</strong>: Opt-in LCEVC enhancement-layer decoding for adaptive streams.</li><li><strong>Muted-autoplay fallback for split native-audio tracks</strong>: rolls video muted + shows the tap-to-unmute pill instead of freezing.</li><li><strong>Extension: detect <code>.mpd</code> (DASH) URLs in page scan.</strong></li><li><strong>VS Code extension: adaptive streaming via URL</strong> — <code>Movi: Open Video from URL</code> plays <code>.m3u8</code> / <code>.mpd</code> / <code>.ism</code> by loading them directly in the player engine (no host byte-range proxy); progressive files still use the proxy.</li><li><strong>VS Code extension: <code>.ts</code> (MPEG-TS) added to the open-file dialog</strong> (not the single-click association).</li></ul><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>DRM key-system order</strong>: Widevine → PlayReady → FairPlay.</li><li><strong>Manifests load directly, never via <code>/proxy</code></strong>: fixes relative segment resolution and the proxy content-type allowlist for <code>.m3u8</code> / <code>.mpd</code> / <code>.ism</code>.</li><li><strong>Size resolution hardened</strong>: HEAD → ranged GET → plain GET retry chain for CDNs that strip <code>Content-Length</code>.</li><li><strong>deps</strong>: add <code>shaka-player ^4.11.2</code>, <code>dashjs ^5.2.0</code>; bump <code>hls.js</code> to <code>^1.6.16</code>.</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Robust startup</strong>: visible play affordance on blocked autoplay, guarded first-play seek, background-tab autoplay deferred until visible.</li><li><strong>Don&#39;t flash wrapper errors mid-fallback</strong>: no spurious &quot;Try Software Decoding&quot; while falling back behind Shaka.</li><li><strong>HTTP errors surface real messages</strong>: <code>403</code> / <code>404</code> / <code>5xx</code> map to access-denied / not-found / server-error.</li><li><strong>Wake lock</strong>: skip while hidden, retry transient failure, re-acquire on visible/resize.</li><li><strong>Don&#39;t collapse a loading/errored video into the 56px audio strip on resize.</strong></li><li><strong>App proxy</strong>: don&#39;t proxy same-origin URLs (522 loop); don&#39;t magic-sniff tiny range probes.</li><li><strong>Volume slider opens on first touch; ambient re-applies after <code>src</code> change.</strong></li><li><strong>Cover-art backdrop blur</strong> via CSS <code>filter:blur()</code> (works in Safari &lt; 17); audio-only <code>poster</code> renders as album art.</li><li><strong>Audio-only replay/loop restarts the native <code>&lt;audio&gt;</code>; no context menu without <code>controls</code>.</strong></li></ul><h2 id="_0-3-0-2026-06-02" tabindex="-1">[0.3.0] - 2026-06-02 <a class="header-anchor" href="#_0-3-0-2026-06-02" aria-label="Permalink to &quot;[0.3.0] - 2026-06-02&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Signalsmith Stretch audio rate-change pipeline</strong>: Replaced SoundTouch with Signalsmith Stretch as the sole pitch-preserving time-stretcher.</li><li><strong>First-class audio-only support with strip UI</strong>: Audio-only files play through the canvas pipeline with a dedicated audio strip UI (cover art, title, progress bar, controls).</li><li><strong>Muted-autoplay fallback with tap-to-unmute</strong>: When autoplay is blocked, the player starts muted and shows an &quot;unmute&quot; pill overlay.</li><li><strong>Cover art display for audio</strong>: JS-only album art extraction via an isolated demuxer context.</li><li><strong>Custom <code>SourceAdapter</code> for <code>&lt;movi-player&gt;</code> and <code>MoviPlayer</code> (closes #7)</strong>: Plug any custom byte protocol directly into the element or player.</li><li><strong>File-source preload settling gate</strong>: <code>play()</code> and resume gated until initial preload fills.</li><li><strong>YouTube-style centre play button</strong>: Always-visible large play/pause icon.</li><li><strong>Unified controls chrome — dark gradient bar + redesigned OSD</strong>: Opaque backgrounds replace backdrop-filter blurs.</li><li><strong>Extension: playlist shuffle, autoplay toggle, next button</strong></li><li><strong>Extension: hover-probe links + opt-in toggle + flag detection</strong></li><li><strong>Compare page (<code>/compare</code>)</strong>: Side-by-side native vs movi-player.</li><li><strong>VS Code extension — URL streaming, multi-window commands, Activity Bar entry</strong></li><li><strong>Homepage redesign</strong></li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>4K playback rate cap raised to 2x</strong> (only 8K+ capped at 1.5x)</li><li><strong>Renderer queue split for 4K vs 8K</strong></li><li><strong>UI update loop throttled to 4Hz</strong></li><li><strong>Volume slider uses perceptual (log) gain curve</strong></li><li><strong>Ambient mode FBO mirror</strong> (no more full canvas readback)</li><li><strong>Thumbnail hover latency cut</strong></li><li><strong>Dropped backdrop-filter blur from all UI surfaces</strong></li><li><strong>README redesigned</strong>, browser support updated (Firefox 130+)</li><li><strong>AGENTS.md shipped in package</strong></li></ul><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Decode</strong>: RASL leading pictures after CRA/BLA seek, DoVi/HDR HEVC on hardware, open-GOP HEVC fallback, tiny packet drop, AV1 Temporal Delimiter OBU</li><li><strong>Seek</strong>: prefer IDR fall back to CRA, resume into buffering on timeout</li><li><strong>Playback</strong>: mid-playback decode-error recovery, auto-start on rate restore, rapid seeks stuck, stall detection during recovery, audio tail on rate change, EOF detection</li><li><strong>Audio</strong>: log gain curve, pitch-shift at startup, audio-only shortcuts, near-end seek clipping</li><li><strong>UI</strong>: controls flash, play/pause icon state, centre play flickering, cursor hiding, loop toggle replay</li><li><strong>Canvas</strong>: display-p3 fallback, rec2100-pq preservation</li><li><strong>Thumbnail</strong>: recreate dead WebCodecs decoder</li><li><strong>Extension</strong>: video link detection, loop replays</li><li><strong>HTTP</strong>: surface server errors</li></ul><h2 id="_0-2-3-2026-05-07" tabindex="-1">[0.2.3] - 2026-05-07 <a class="header-anchor" href="#_0-2-3-2026-05-07" aria-label="Permalink to &quot;[0.2.3] - 2026-05-07&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Subtitle Delay / Offset (closes #4)</strong>: Shift subtitle timing relative to video — <code>subtitledelay</code> attribute, <code>subtitleDelay</code> property, <code>setSubtitleDelay()</code> / <code>getSubtitleDelay()</code> API methods, and a new <code>subtitledelaychange</code> CustomEvent. Sign convention matches VLC/mpv (positive = subtitles later). UI cap ±300s with widened input. Z/X hotkeys nudge by 100ms per press; OSD shows the current offset. Auto-prefetch when delay becomes non-zero so negative offsets work (cues from stream positions ahead of the demuxer cursor). Applied at the renderer&#39;s active-cue check so a single offset works for text and image (PGS/DVB) cues without re-decoding.</li><li><strong>Subtitle Customization Panel</strong>: <code>subtitlesize</code>, <code>subtitlecolor</code>, <code>subtitlebg</code>, <code>subtitleedge</code> attributes, plus an in-player customize panel persisted to localStorage. Size multiplier drives both bitmap (PGS/VOBSUB) and text (SRT/ASS/VTT) cues; edge style applies to text subs.</li><li><strong>Subtitle Transcript Browser</strong>: Full-cover panel with search, click-to-seek, active-cue highlight, italic/bold/entity rendering, and delay-aware timestamps. Click on a live caption opens the transcript at the current cue. Backed by a native <code>movi_prefetch_subtitle_cues</code> that uses <code>AVDISCARD_ALL</code> so a 700 MB scan touches only subtitle packets, not every audio/video body.</li><li><strong>Karaoke Captions for VTT</strong>: Tag-only-token folding, min-width anchor measured offscreen, render-key cache to stop the 60fps <code>innerHTML</code> rewrite that prevented fade-in during playback. Format-aware backdrop (VTT-only).</li><li><strong>Premuxed Quality Menu</strong>: Multiple <code>&lt;source data-height=&quot;...&quot;&gt;</code> children give a YouTube-style quality picker for plain MP4/MKV files — no HLS manifest needed. Adopt/release native <code>&lt;audio&gt;</code> across switches preserves the user-activation token so the next switch isn&#39;t blocked by autoplay policy.</li><li><strong>Multi-Language Audio via <code>&lt;source kind=&quot;audio&quot;&gt;</code></strong>: Two or more audio <code>&lt;source&gt;</code> tags with <code>srclang</code> (or <code>label</code>) become parallel language tracks; the player surfaces the audio-language menu and <code>getAudioLangs()</code> / <code>selectAudioLang()</code> work exactly as for muxed tracks. Default pick: explicit <code>default</code> / <code>data-default</code> → first locale match (<code>navigator.language</code> prefix) → first track. Single <code>&lt;source kind=&quot;audio&quot;&gt;</code> continues to use the legacy split-audio path.</li><li><strong>External Subtitles via <code>&lt;track&gt;</code></strong>: Standard <code>&lt;video&gt;</code>-style declarative markup — <code>&lt;track kind=&quot;subtitles&quot;&gt;</code>, <code>kind=&quot;captions&quot;</code>, or no <code>kind</code> are recognized. Reads <code>srclang</code>, <code>label</code>, and <code>data-format</code> (defaults to VTT, set <code>srt</code> for SRT sidecars). Lets integrators ship full caption configurations as plain HTML without wiring up <code>source({ subtitles: [...] })</code> from JS.</li><li><strong>Host Fullscreen Handoff</strong>: New cancelable <code>movi-fullscreen-request</code> CustomEvent + <code>setHostFullscreen(active)</code> method. Lets embedders (VS Code webviews, custom app shells) take over fullscreen with their own chrome while keeping the player&#39;s toolbar icon, OSD, and context-menu label in sync. Fullscreen state is now reflected in the context-menu label.</li><li><strong>File Revoked Event</strong>: <code>filerevoked</code> CustomEvent fires when the browser silently revokes a <code>File</code> handle (mobile background / memory pressure). <code>FileSource</code> races each chunk read against an 8s timeout — no more demuxer hanging forever — and surfaces the failure via a one-shot <code>onRevoked</code> callback on <code>MoviPlayer</code>.</li><li><strong><code>MoviPlayer.hasAudibleSource()</code></strong>: Unified gate covering muxed audio, split native <code>&lt;audio&gt;</code>, <em>and</em> HLS audio (which lives inside the hidden native <code>&lt;video&gt;</code>). Used internally to decide whether to show volume controls / accept volume hotkeys.</li><li><strong>VS Code Extension</strong>: New <code>vscode-extension/</code> package (Marketplace 0.2.5). Webview-hosted player registered as a CustomEditor — single-click opens any MP4/MKV/HEVC/AV1/WebM/MOV/TS file VS Code can&#39;t natively play. True streaming via a custom <code>DataSource</code> (webview&#39;s <code>File</code> proxy delegates <code>slice().arrayBuffer()</code> to extension-host <code>fs.createReadStream</code> chunks); memory cost drops from O(filesize) to ~chunk size, so multi-GB and 8K HDR files no longer hit the 4 GB Blob limit. Movi fullscreen toggle hides workbench chrome with auto-cleanup on crash. OS wake lock (<code>caffeinate -i</code> / <code>systemd-inhibit</code> / <code>SetThreadExecutionState</code>) held during fullscreen. Multi-window playback via <code>movi.openInNewWindow</code>. Output channel surfaces bundled-player logs.</li><li><strong>Web App Explorer-Style Playlist</strong>: Folder hierarchy tree with collapsible groups + guide rail, multi-select, live search (folders auto-expand on match), keyboard navigation (Tab toggle, Up/Down/Enter, Esc). Thumbnails + metadata cached in IndexedDB so reopening the same files skips every WASM call. SEO overhaul, landing animations, gradient circle brand mark.</li><li><strong>Chrome Extension Explorer Playlist</strong>: Folder tree, breadcrumb, badges, progress, drag/drop, multi-file + folder picking. Shared isolated WASM instance (2-instance budget) for thumbnail generation, cached in IndexedDB across sessions. Install detection on moviplayer.com hides the &quot;Add to Chrome&quot; prompt when the extension is already present. Gradient circle play-button branding to match the main app.</li><li><strong>Stats 8K / 16K Tiers</strong>: <code>4320p</code> (8K) and <code>8640p</code> (16K) labels in both native and HLS stats paths — previously bucketed as 4K.</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>HLS Volume Controls Now Visible</strong>: Volume button, <code>ArrowUp</code> / <code>ArrowDown</code> hotkeys, and volume OSD were gated only on muxed/split audio, so HLS streams (audio inside the native <code>&lt;video&gt;</code>) had no mute control. Consolidated behind <code>hasAudibleSource()</code> so the HLS path is covered too.</li><li><strong>Audio Decode Stays Running While Muted</strong>: The demux loop no longer drops audio packets when muted — <code>AudioRenderer</code> keeps gain at 0 instead. Fixes the &quot;atak atak&quot; judder on unmute, where the audio clock pivoted forward to the demuxer&#39;s lookahead (~1–3s ahead of presentation) and <code>CanvasRenderer</code> chased it 25%/frame.</li><li><strong>Bluetooth A2DP Keepalive</strong>: Pause path now suspends the AudioContext but starts a near-silent looping <code>&lt;audio&gt;</code> element so the OS audio session stays claimed. BT devices stop dropping/re-pairing on every pause without re-introducing the &quot;2–3s jump-ahead on resume&quot; regression.</li><li><strong>DPR-Scaled Canvas Backbuffer</strong>: Canvas backbuffer scales with <code>devicePixelRatio</code> (capped at 2×) so downsampling 4K/8K sources stays sharp. CSS dimensions remain in logical pixels.</li><li><strong>Encrypted Source Static Import</strong>: <code>EncryptedHttpSource</code> hoisted to a top-level import — no more async boundary on every encrypted load. Matches the other source adapters.</li><li><strong>FFmpeg Bumped to n8.1.1</strong>: Picks up upstream point-release fixes on the n8.1 branch. <code>dvbsubtitle</code> / <code>dvdsubtitle</code> decoders renamed to <code>dvbsub</code> / <code>dvdsub</code> to match.</li><li><strong>Subtitle Default Sizing</strong>: Bumped the text-subtitle base size and replaced the desktop-era 60px floor on bottom padding with a height-proportional 8% (24px floor) so subtitles don&#39;t crowd into the middle of small embeds.</li><li><strong>Menu Animations</strong>: Pop-in / pop-out on the audio, subtitle, quality, and speed dropdowns plus a fade between the customize panel and track list. Bottom-controls dropdowns enforce one-at-a-time. Click on the player area closes any open menu instead of toggling play/pause.</li><li><strong>Keyboard Shortcuts Ignored While Typing in Inputs</strong>: Hotkeys no longer fire when an input/textarea inside the shadow DOM is focused.</li><li><strong>Audio Menu Always Shows Language Code</strong>: <code>formatAudioBadge</code> previously dropped the language code when channel info was available, so muxed tracks from MKV/MP4 displayed only &quot;AAC Stereo&quot; with no way to tell languages apart.</li><li><strong>COOP/COEP Hard-Required</strong>: README/docs corrected — the player hard-blocks without <code>Cross-Origin-Opener-Policy: same-origin</code> + <code>Cross-Origin-Embedder-Policy: require-corp</code>. Surfaces a &quot;Security Headers Missing&quot; diagnostic instead of a cryptic timeout. Mention <code>coi-serviceworker</code> as a static-host workaround.</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>~1s Fullscreen Freeze</strong>: ResizeObserver fires repeatedly during the fullscreen animation. Each call set <code>canvas.width</code> twice (in <code>updateCanvasSize</code> and <code>CanvasRenderer.resize</code>), clearing the WebGL framebuffer on every burst. Coalesced same-size resizes, dropped the duplicate width/height assignment, dropped the <code>&lt;video&gt;.width/height</code> no-ops.</li><li><strong>WebGL Context Loss Recovery (Mobile)</strong>: Capture canvas to JPEG on <code>visibilitychange→hidden</code> while the GL context is alive; on return, hide instantly if <code>gl.isContextLost()</code> is false, otherwise leave it up so <code>handleContextLost</code>/<code>handleContextRestored</code> can run recovery without a corrupt framebuffer flashing through. Restored <code>isLoading</code> clear so <code>initializePlayer</code> doesn&#39;t early-return after long minimize. 5s cooldown between audio-resync seeks prevents stutter loops on slow software audio decoders.</li><li><strong>HLS First-Frame Black</strong>: Manifests without <code>RESOLUTION</code> caused <code>configure(0,0)</code> on the canvas renderer, producing a black frame that only cleared on the next ResizeObserver tick. Defer configure to <code>&lt;video&gt; loadedmetadata</code> when manifest dims are missing.</li><li><strong>HLS Quality Badge / Fit Animation</strong>: Re-emit <code>tracksChange</code> on <code>LEVEL_SWITCHED</code> so the gear badge reflects the active rendition in Auto mode. Skip smoothing-state reset on same-size canvas resizes so fit-mode toggles can lerp instead of snapping; clone last frame in the direct-render path so HLS paused redraws have a source to animate against.</li><li><strong>Pause→Resume 2–3s Jump-Ahead</strong>: Pause now preserves scheduled buffers and sync anchors exactly, so the first packet drained from <code>pendingPrebufferPackets</code> (whose timestamp is the demuxer&#39;s lookahead) doesn&#39;t become the new <code>firstBufferMediaTime</code> anchor on resume.</li><li><strong>Aspect-Ratio Change While Paused</strong>: Fit-mode change now repaints the canvas after a seek-to-paused and animates via a dedicated RAF loop instead of snapping. Poster overlay tracks the active fit mode, lets pointer events pass through so dblclick / gesture handlers still fire, and stays hidden until a source is set.</li><li><strong>Mobile Speaker Tap</strong>: Switched from <code>PointerEvent.pointerType</code> (Android Chrome synthesizes click with <code>pointerType=&quot;mouse&quot;</code> from a touch tap) to <code>matchMedia(&quot;(hover: none)&quot;)</code> as the primary touch signal. <code>composedPath()</code> to cross shadow boundary in the close-volume listener. Mobile media query no longer hides the slider on <code>.active</code>.</li><li><strong>Embed Security Headers Diagnostic</strong>: Every <code>src=</code> change now re-runs <code>checkSecurityHeaders()</code>, so reused players surface &quot;Security Headers Missing&quot; instead of a cryptic &quot;Failed to open media: Timeout at 0&quot;.</li><li><strong>Pause Buffering Loop / Single-Track Streams</strong>: Pause buffer loop required both audio and video targets via AND, so audio-only / video-only streams never satisfied it and ran to the 3000-packet safety cap (~30s of demux), surfacing as a burst of cache-read spam after pause. Now only checks targets for tracks that exist.</li><li><strong>A/V Drift Loop on Hardware Burst Decoders</strong>: Hardware decoders that emit 8K frames in bursts queued many future-PTS frames; on &gt;60Hz displays the fallback drained them faster than wall-clock and tripped the audio-desync resync seek loop. Reject frames more than one frame interval ahead of playback time.</li><li><strong>Audio-less Video in Background Tab</strong>: Without an audio track, the background <code>processLoop</code> had no backpressure (video decode skipped, no audio buffer to fill), so the demuxer raced to EOF in seconds. Pause on hide and auto-resume on visible.</li><li><strong>Volume Keys for Native Audio Sources</strong>: Hotkeys + OSD gated on <code>getAudioTracks().length</code> (empty for split video/audio sources). Now also accept <code>hasNativeAudio()</code>.</li><li><strong>Buffered Bar Stability</strong>: Buffered bar is now monotonic between seeks; pause-time buffering no longer pushes past <code>HttpSource</code>&#39;s buffered end and trigger a window-resetting refetch.</li><li><strong>PGS Subtitles On-Canvas</strong>: Image-subtitle overlay was sized in DPR-scaled buffer pixels, pushing the flex-anchored bitmap off-screen on retina. Switched to the canvas&#39;s CSS rect (matching the text-subtitle path).</li><li><strong>Skip A/V Desync Check When Muted</strong>: Demux loop drops audio decode while muted, so <code>maxScheduledMediaTime</code> freezes and <code>getAudioClock()</code> clamps to a stale value — disabled the 500ms desync detector while muted.</li><li><strong>No Corrective Seek After Unmute</strong>: Reset the desync cooldown on unmute so the audio clock can catch up first instead of forcing a resync seek (visible as a loading shutter).</li><li><strong>Progress Handle at 0%</strong>: Dropped the <code>Math.max(1, …)</code> floor so the handle sits at 0% at the start instead of jumping in from 1%.</li><li><strong>Pre-Play Seek</strong>: Re-arm the <code>seekTargetTime</code> filter on first-play re-seek so Open-GOP recovery frames (1–2s behind the seek target) get dropped instead of presented; matching drop on resume from pause.</li><li><strong><code>getCurrentPlaybackTime</code> Frozen When Paused</strong>: <code>updateActiveSubtitle</code> called via <code>setSubtitleCues</code> during pause can no longer jump to a wall-clock-driven time.</li><li><strong>PiP Exit Buffer Resize</strong>: Invalidate <code>_lastCanvasW/H</code> on PiP exit so the buffer resizes back to host dimensions instead of staying pinned at PiP resolution.</li><li><strong>Seek OSD Accuracy</strong>: Track the actual delta between the pre-seek time and the clamped target instead of a fixed 10s step. Anchor chained presses on the previous target. Dismiss the OSD on a boundary hit / sub-second / NaN delta.</li><li><strong>Coalesce Rapid <code>currentTime</code> Sets</strong>: Overlapping seeks now collapse into a single tail seek instead of queueing them all.</li><li><strong><code>preventScroll</code> on Hover Focus</strong>: <code>focus()</code> on mouseenter no longer yanks the page when the player is partly off-screen.</li><li><strong>Subtitle Re-render on Resize via rAF</strong>: Previously a burst per ResizeObserver tick stalled the presentation loop on window drags.</li><li><strong>Centre Non-VTT Subtitle Lines</strong>: Multi-line SRT cues (e.g. <code>&quot;- A long line\\n- short&quot;</code>) now sit at the player&#39;s centre instead of drifting left.</li><li><strong>Worker /proxy Probe Failures</strong>: Transient probe errors no longer get misreported as <code>415 Unsupported Media Type</code>.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>WebCodecs team outreach playbook (<code>docs/webcodecs-outreach.md</code>).</li></ul><h2 id="_0-2-2-2026-04-26" tabindex="-1">[0.2.2] - 2026-04-26 <a class="header-anchor" href="#_0-2-2-2026-04-26" aria-label="Permalink to &quot;[0.2.2] - 2026-04-26&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong><code>postertime</code> Attribute</strong>: Generate a native-resolution poster from any timestamp without an explicit <code>poster</code> URL. Accepts <code>&quot;10%&quot;</code>, <code>&quot;5&quot;</code>, <code>&quot;1:30&quot;</code>, or <code>&quot;0:01:30&quot;</code>. Uses an isolated thumbnail pipeline (WASM + <code>ThumbnailBindings</code>), respects rotation metadata, and is race-guarded so in-flight generators can&#39;t paint stale frames after a <code>src</code> change.</li><li><strong><code>dispose()</code> Method</strong>: Tears down the internal player and resets transient UI (subtitles, timeline, time, title, generated poster) back to the no-source state. Called automatically on every <code>src</code> change so playlist-style flows never leak state between sources. Safe to call when nothing is loaded.</li><li><strong><code>playing</code> Getter</strong>: Read-only boolean that&#39;s <code>true</code> only while the player is actively playing — distinguishes it from <code>ready</code>, <code>loading</code>, <code>seeking</code>, and <code>buffering</code> states (precise inverse of <code>paused</code>).</li><li><strong><code>MoviElement.cleanVideoTitle(filename)</code> Static</strong>: Utility exposed for playlist UIs to derive the same cleaned title the player uses internally — useful for computing the resume localStorage key (<code>movi-resume:&lt;cleanVideoTitle(name)&gt;</code>).</li><li><strong>Folder Playlist (web demo app)</strong>: Sidebar/below-player playlist via File System Access API (with <code>webkitdirectory</code> fallback). YouTube-style items with thumbnail, duration, HDR chip, codec/quality/size meta, and watched-progress bar. Lazy thumbnail generation, natural-sort, autoplay-next toggle, drag-and-drop multi-file support.</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong><code>play()</code> Semantics</strong>: Now queues a play intent during <code>isLoading</code> and flushes it from <code>initializePlayer()</code>&#39;s finally block — matches <code>HTMLMediaElement</code> behavior. Previously bailed silently when called during load.</li><li><strong>Software Decoder Fallback Per-Source</strong>: Choosing &quot;Try software&quot; no longer sticks across <code>src</code> changes. The next video gets a fresh hardware-decode attempt; the <code>sw</code> attribute is cleared on dispose.</li><li><strong>Encrypted Playback Protocol</strong>: <code>EncryptedHttpSource</code> rewritten — block prefetch high-water/low-water tuning, concurrent-stream cap, <code>getPosition()</code> reports the real read cursor, and parent position field is kept in sync so buffer math stays honest. Encrypted-server ported to match the new protocol.</li><li><strong>Buffer Tuning</strong>: Runtime tuning of prefetch high-water, refill threshold, and block cache cap via the existing <code>buffersize</code> attribute. README/docs corrected to clarify the value is in <strong>megabytes</strong> (not seconds) and applies to both HTTP and encrypted sources.</li><li><strong>Production Bundles</strong>: Re-enabled terser <code>drop_console</code> and <code>drop_debugger</code> so release builds ship without dev-only logging.</li><li><strong>Build Stability</strong>: <code>app:release</code> script ties build + R2 upload + worker deploy into a single command. Build version cache-bust scoped to the quoted <code>__BUILD_VERSION__</code> literal so unrelated lines aren&#39;t rewritten.</li></ul><h3 id="fixed-9" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-9" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Post-Seek A/V Sync</strong>: Cap the post-seek audio gap at 200ms — when the first video frame after a seek arrives late (sparse keyframes / slow HEVC+HDR decoders), sync the clock to video time and drop stale audio instead of syncing to the earliest audio packet. Small gaps still prefer audio for continuity.</li><li><strong>Pre-Play Seek Position</strong>: Scrubbing the timeline before pressing play no longer resets to 0 — the first-play poster-seek now reads <code>clock.getTime()</code> instead of a hardcoded start time. Pipeline is flushed on user seek so prebuffered start audio doesn&#39;t briefly play before jumping to the target.</li><li><strong>Fully-Cached Buffered Duration</strong>: Buffered range now reports the full media duration when the file is fully cached, instead of stopping at the last network read.</li><li><strong>Buffer Indicator Race</strong>: Collapsed the seek-race scan sweep that could draw a phantom buffered range mid-seek.</li><li><strong>Encrypted Thumbnails</strong>: Share the main source for thumbnail reads instead of opening a parallel session — cuts redundant token churn. Concurrent stream cap prevents seek-storm thrash. Hardened thumbnail read failures (no more fragile retry/cooldown loop).</li><li><strong>Worker <code>/proxy</code> Empty 206</strong>: Retry empty 206 responses from upstream before streaming back, so transient origin hiccups don&#39;t surface as broken playback.</li><li><strong>Worker Probe Failures</strong>: Transient probe errors no longer get misreported as <code>415 Unsupported Media Type</code>.</li><li><strong>TMDb Title Parser</strong>: Detect TV shows when the episode title trails the <code>SxxExx</code> code (e.g., <code>Show.S05E01.Title</code>).</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong>Worker Referer Allowlist</strong>: <code>/proxy</code> and <code>/eproxy</code> endpoints now gate requests by Referer to block hotlinking from unauthorized origins.</li><li><strong>Worker Magic-Byte Validation</strong>: <code>/proxy</code> responses are validated against expected media magic bytes before being streamed back, mitigating MIME confusion attacks.</li></ul><h2 id="_0-2-1-2026-04-16" tabindex="-1">[0.2.1] - 2026-04-16 <a class="header-anchor" href="#_0-2-1-2026-04-16" aria-label="Permalink to &quot;[0.2.1] - 2026-04-16&quot;">​</a></h2><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Persistent Preferences</strong>: <code>stableVolume</code>, <code>ambientMode</code>, and <code>hdr</code> toggles now persist via OPFS alongside <code>volume</code>, <code>muted</code>, and <code>playbackRate</code>. User toggles win over HTML attribute defaults on subsequent loads.</li><li><strong>Split-Source Volume Control</strong>: Volume button now visible when a separate native audio element is loaded, even if the video file has no muxed audio track.</li><li><strong>Smart Title Extraction</strong>: VLC-style filename cleaning strips release tags, codecs, and quality markers from tab titles. <code>Content-Disposition</code> filename used when the server provides one.</li><li><strong>Chrome Extension</strong>: Local file playback via popup file picker, drag-and-drop onto the player page, and a redesigned popup layout.</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Context Menu</strong>: Slide-panel variant now only used on touch devices (<code>pointer: coarse</code>); narrow desktop windows get the regular hover-driven menu.</li><li><strong>Context Menu Scrolling</strong>: Max-height clamped to player height with subtle scrollbar styling so tall menus stay accessible on short players.</li><li><strong>Theme Color Cascade</strong>: <code>themecolor</code> attribute now flows to <code>--movi-primary-light</code> and <code>--movi-primary-dark</code> via <code>color-mix</code>, so active menu items and highlights follow the custom theme.</li><li><strong><code>title</code> Attribute</strong>: No longer triggers the browser&#39;s native tooltip on hover — title is rendered only by the in-player overlay.</li><li><strong>Subtitle/Audio Track Menus</strong>: Show language codes alongside track labels for clarity.</li></ul><h3 id="fixed-10" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-10" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Short Video Stutter</strong>: Prebuffer media before <code>ready</code> so <code>play()</code> doesn&#39;t immediately stall on short clips.</li><li><strong>Background Audio at 50/60 fps</strong>: Skip video decode while hidden so audio keeps flowing on high-fps content.</li><li><strong>Narrow Viewport Controls</strong>: Buttons, gaps, and center play button tightened on viewports ≤ 480px to prevent the controls bar from overflowing the player box on iPhone 12 Pro-class widths.</li><li><strong>Empty State Placement</strong>: &quot;No Video&quot; placeholder no longer clips into the controls bar on short/narrow players.</li><li><strong>OSD Speed Icon</strong>: Correct speed icon shown when playback rate changes via hotkeys/context menu.</li></ul><h2 id="_0-2-0-2026-04-09" tabindex="-1">[0.2.0] - 2026-04-09 <a class="header-anchor" href="#_0-2-0-2026-04-09" aria-label="Permalink to &quot;[0.2.0] - 2026-04-09&quot;">​</a></h2><h3 id="added-11" tabindex="-1">Added <a class="header-anchor" href="#added-11" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Ambient Mode</strong>: Dynamic letterbox glow that samples video colors in real-time. Smooth 60fps color transitions via WebGL clearColor. Toggle with <code>G</code> key or context menu. Works in fullscreen (letterbox) and normal mode (external wrapper). <code>ambientmode</code> attribute.</li><li><strong>Split Source Support</strong>: Separate video, audio, and subtitle file URLs via <code>videosrc</code>, <code>audiosrc</code>, <code>subtitlesrc</code> attributes.</li><li><strong>PGS Image Subtitles</strong>: Bitmap subtitle decoding with zlib decompression support.</li><li><strong>Network Disconnect Recovery</strong>: Intelligent CORS vs transient network failure detection (3-strike threshold). Online-event-aware backoff for instant retry on reconnection. Auto re-seek on recovery. 30s timeout on offline wait.</li><li><strong>Document Picture-in-Picture</strong>: Floating video window with play/pause, seek, mute, progress bar, time display, keyboard shortcuts, and back-to-tab button. Portrait video sizing. Rotation save/restore on PiP enter/exit.</li><li><strong>DRM Support</strong>: <code>drm</code> and <code>licenseurl</code> attributes for HLS streams with Widevine/FairPlay via EME API.</li><li><strong>HLS Quality Menu</strong>: Duplicate resolutions show bitrate (e.g., &quot;1080p · 5000 kbps&quot;).</li><li><strong>HLS Nerd Stats</strong>: Video codec, resolution, quality, frame rate, bitrate, buffer, HLS level, bandwidth, live latency, frames decoded/dropped.</li><li><strong>VLC-style Shortcuts</strong>: <code>V</code> subtitles, <code>B</code> audio, <code>+/-</code> speed, <code>L</code> loop, <code>U</code> stable volume, <code>H</code> HDR, <code>P</code> PiP, <code>G</code> ambient, <code>A</code> aspect ratio.</li><li><strong>Aspect Ratio Controls</strong>: <code>A</code> key cycles contain/cover/fill/zoom. Sub-menu with icons in context menu and bottom controls.</li><li><strong>Stable Volume</strong>: DynamicsCompressorNode for loudness normalization. Opt-in via <code>stablevolume</code> attribute.</li><li><strong>Nerd Stats</strong>: Press <code>I</code> for codec, resolution, FPS, decoder type, buffer health, color info, and live network/disk activity graph.</li><li><strong>Timeline</strong>: Press <code>T</code> for auto-generated thumbnail strip with chapter support. Arrow key navigation, click-to-seek.</li><li><strong>Chapter Support</strong>: Extract chapters from video metadata. Chapter markers on progress bar, chapter titles in seek tooltip.</li><li><strong>Video Rotation</strong>: Press <code>R</code> to rotate 90°. Metadata rotation auto-applied. Disabled during PiP.</li><li><strong>Keyboard Shortcuts Panel</strong>: Press <code>?</code> to view all shortcuts.</li><li><strong>Resume Playback</strong>: <code>resume</code> attribute saves position to localStorage with resume/start-over dialog.</li><li><strong>Encrypted Playback</strong>: AES-256-GCM chunked encryption with HMAC-SHA256 signed requests.</li><li><strong>Background Audio</strong>: Video keeps playing audio when tab is in background via Web Worker timer fallback.</li><li><strong>Chrome Extension</strong>: Popup with &quot;Paste &amp; Play&quot; and &quot;Play from Computer&quot;, context menu on video links, play button overlay on detected URLs.</li><li><strong>Privacy Policy</strong>: Published at docs site for Chrome Web Store compliance.</li></ul><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Buffering state now stops presentation loop so frames accumulate for reliable recovery.</li><li>Buffering exit requires video frames ready (with 3s fallback for async decoder delays).</li><li>Pause during buffering allowed from all UI controls (click, keyboard, buttons, PiP, context menu).</li><li><code>buffering → ended</code> state transition allowed for EOF during rebuffer.</li><li>Invalid packet size at EOF treated as EOF (not fatal error) for FFmpeg stale buffer data.</li><li>HDR icon changed to text badge style in OSD and context menu (matches bottom controls).</li><li>Extension description rewritten to remove excessive format keywords (Chrome Web Store compliance).</li><li>Console logs dropped in production build.</li></ul><h3 id="fixed-11" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-11" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Hardware decoder error recovery with keyframe cache and software fallback.</li><li>Seek and play/pause during buffering state.</li><li>Network disconnect causing permanent CORS misclassification when <code>navigator.onLine</code> lags.</li><li>Stale stream loops from leaked online event listeners during backoff.</li><li>Multiple concurrent fetch loops after network recovery.</li><li>Clock advancing during buffering (presentation loop consuming frames).</li><li>PiP rotation clipping — rotation reset on PiP enter, restored on close.</li><li>PiP portrait video oversized — height-limited sizing for portrait aspect ratios.</li><li>Pause-seek loading stuck — <code>VideoDecoder.flush()</code> 1s timeout with reset+reconfigure fallback.</li><li>EOF not triggering — relaxed condition with 0.5s tolerance.</li><li>PiP canvas restore using <code>shadowRoot</code> directly.</li><li>PiP frame freeze on tab switch with <code>isPiPActive</code> guard.</li><li>EncryptedHttpSource network resilience matching HttpSource.</li><li>Nerd stats graph fullscreen positioning and CSS specificity.</li></ul><h2 id="_0-1-5-2026-02-15" tabindex="-1">[0.1.5] - 2026-02-15 <a class="header-anchor" href="#_0-1-5-2026-02-15" aria-label="Permalink to &quot;[0.1.5] - 2026-02-15&quot;">​</a></h2><h3 id="added-12" tabindex="-1">Added <a class="header-anchor" href="#added-12" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Pitch preservation for playback rate changes</li><li>Pitch preservation support for HLS playback</li><li>MediaSession API integration for background playback and media controls</li><li>HTTPS support for local development environment</li></ul><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Simplified error messages to be more concise and consistent</li><li>Replaced all hardcoded purple colors with CSS variables (--movi-primary) for full theme customization</li><li>Enhanced center play button with theme color by default</li><li>Updated loading spinner with responsive sizing and theme-aware colors</li></ul><h3 id="fixed-12" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-12" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Improved playback stability with enhanced error handling and timeout management</li><li>Resolved audio-video sync issues with hardware decoding</li><li>Distinguished 403/401/404 errors from CORS errors for better error reporting</li><li>CORS errors now propagate immediately instead of waiting for timeout</li><li>Title bar z-index now properly positioned below control menus in mobile view</li><li>Center play button backdrop blur now enabled on mobile/touch devices</li><li>Controls no longer auto-hide when menus are open on mobile</li></ul><h2 id="_0-1-4-2026-02-11" tabindex="-1">[0.1.4] - 2026-02-11 <a class="header-anchor" href="#_0-1-4-2026-02-11" aria-label="Permalink to &quot;[0.1.4] - 2026-02-11&quot;">​</a></h2><h3 id="fixed-13" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-13" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Resolved video stalling during playback and improved A/V sync</li><li>Playback speed changes now take immediate effect on audio</li><li>Auto-unmute when volume slider is moved while muted</li><li>Mute button now correctly toggles audio muting</li></ul><h2 id="previous-versions" tabindex="-1">Previous Versions <a class="header-anchor" href="#previous-versions" aria-label="Permalink to &quot;Previous Versions&quot;">​</a></h2><p>See git commit history for changes in versions prior to 0.1.4.</p>',97)])])}const p=o(r,[["render",i]]);export{g as __pageData,p as default};
